programs.sol:
"""Approximate this component with lexical and short phrase rules.

The main negative responses concern symbols and rituals: especially 象征,
'symbolic', and split endings such as symbol + ize. Cultural vocabulary in
the preceding forty tokens strengthens symbol nouns; technical vocabulary
weakens 'symbolic'. These context rules are heuristics, not a complete account.

Separate rules cover Java names, grammatical words, protocol delimiters,
the Chinese character 挽, Russian 'order', and a Russian adjective ending.
Most unrecognized tokens receive the small training-average baseline.
The state resets at document boundaries and stores only two tokens and two
forty-token keyword timers. No model weights or arbitrary token ids are used.
"""
READS = ()

SYMBOL_LANGUAGE = {
    'symbolism': -0.26,
    'signify': -0.31,
    'signifies': -0.23,
    'gesture': -0.29,
    'gestures': -0.20,
    'ritual': -0.18,
    'rituals': -0.16,
    'ceremony': -0.19,
    'tangible': -0.35,
    'trophy': -0.41,
    'meaningless': -0.38,
    'meaningful': -0.10,
    '意味着': -0.32,
    '仪式': -0.28,
    '签约仪式': -0.46,
}
CULTURAL = frozenset('''sacred national pride powerful status religious
    spiritual royal ritual ceremony dragon hope resilience strength identity
    unity ideology courage buddhist christian shaman'''.split())
TECHNICAL = frozenset('''mathematical equation equations algebra integral
    transform transforms computation compiler variables function code quantities
    quantity characters unicode identifier identifiers character digits binary
    parser programming computer mathematics'''.split())
SYMBOL_ENDINGS = {
    'ic': -0.49,
    'ically': -0.37,
    'ism': -0.26,
    'ize': -0.43,
    'izes': -0.43,
    'ized': -0.40,
    'izing': -0.40,
    'ise': -0.40,
    'ised': -0.40,
    'ising': -0.40,
}
JAVA_PACKAGES = {
    '.bukkit': -0.63,
    '.vaadin': -0.53,
    '.appcompat': -0.38,
    '.databind': -0.38,
    '.fasterxml': 0.30,
    '.fxml': 0.30,
}

# Small responses associated with English grammatical categories and markup.
PROTOCOL_BOUNDARIES = {
    '</think>': -0.15,
    '<think>': -0.09,
    '</tool_call>': 0.14,
    '<tool_response>': 0.09,
    '</tool_response>': -0.07,
    '<|im_start|>': -0.04,
    '<|im_end|>': -0.02,
}
TIME_WORDS = frozenset('early late now next later today yesterday tomorrow'.split())
NEGATIVE_PRONOUNS = frozenset('i you he him they their our'.split())
QUANTITY_AND_REFERENCE = {
    'each': -0.06,
    'every': -0.03,
    'some': -0.02,
    'few': -0.045,
    'multiple': -0.07,
    'neither': -0.05,
    'enough': 0.09,
    'same': 0.06,
    'these': 0.038,
    'another': -0.035,
}
FILE_FORMATS = {
    '.js': -0.076,
    '.java': -0.12,
    '.json': -0.136,
    '.yaml': -0.10,
    'json': -0.13,
    'java': -0.078,
}


def background(token, word):
    if token in PROTOCOL_BOUNDARIES:
        return PROTOCOL_BOUNDARIES[token]
    if word in FILE_FORMATS:
        return FILE_FORMATS[word]
    if token in ("'s", '’s'):
        return 0.032
    if token in ("'t", '’t'):
        return -0.045
    if word == 'import':
        return -0.07
    if token.startswith(' '):
        if word in NEGATIVE_PRONOUNS:
            return -0.023
        if word in ('me', 'us'):
            return -0.043
        if word in ('my', 'your', 'her'):
            return 0.015
        if word.endswith(('self', 'selves')):
            return -0.08
        if word in TIME_WORDS:
            return 0.05
        if word in QUANTITY_AND_REFERENCE:
            return QUANTITY_AND_REFERENCE[word]
        if word in ('positive', 'negative'):
            return -0.10
        if word == 'about':
            return -0.044
    return -0.0036


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, cultural, technical = '', '', 0, 0
    else:
        _, previous, before_previous, cultural, technical = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    cultural = 40 if lower in CULTURAL else max(0, cultural - 1)
    technical = 40 if lower in TECHNICAL else max(0, technical - 1)
    value = background(token, word)

    if lower in SYMBOL_LANGUAGE:
        value = SYMBOL_LANGUAGE[lower]
    elif lower in ('symbol', 'symbols'):
        value = -0.09 if token[:1].isspace() else -0.03
        if cultural > 0:
            value = -0.23
    elif lower == 'symbolic':
        value = -0.23 if technical > 0 and cultural == 0 else -0.48
    elif word in ('象征', '象徵'):
        value = -0.77
    elif word.startswith('символ'):
        value = -0.34
    elif token in JAVA_PACKAGES:
        value = JAVA_PACKAGES[token]
    elif word == 'AppCompatActivity':
        value = -0.72
    elif word == '.AppCompatActivity':
        value = -0.25
    elif word == 'TargetException':
        value = -0.97 if before_previous == '.Inv' else -0.47
    elif word == '.ObjectMapper':
        value = 0.69
    elif word in ('XMLLoader', 'FXMLLoader'):
        value = 0.68
    elif word in ('FXML', '@FXML'):
        value = 0.32 if word.startswith('@') else 0.44
    elif word == '挽':
        value = 0.70 if previous == '力' else 0.49

    if previous.strip().lower() in ('symbol', 'symbols', 'symbolic'):
        if token == ' of':
            value = -0.27 if technical > 0 and cultural == 0 else -0.40
        elif not token[:1].isspace():
            value = SYMBOL_ENDINGS.get(lower, value)
    if previous.strip() in ('象征', '象徵'):
        if word == '性':
            value = -0.44
        elif word == '着':
            value = -0.50
    # Locative adjective ending -ическом; 'classical' has a larger response.
    if word == 'ическом':
        value = 0.50 if previous.strip() == 'класс' else 0.24
    # Russian порядок ('order') is often split into stem and noun ending.
    if word == 'поряд':
        value = -0.39
    elif previous.strip() == 'поряд' and word in ('ок', 'ка', 'ком'):
        value = -0.20
    if previous.strip() == 'символ' and word in ('ы', 'ами', 'а', 'ов'):
        value = -0.11
    return (doc, token, previous, cultural, technical), float(value)

programs.luna:
"""Estimate a tiny background activation, with a stronger symbolic-word cue."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()
    if "象征" in word:
        return None, -0.65
    if "symbol" in word:
        return None, -0.45
    if "символ" in word:
        return None, -0.40
    return None, -0.00338

"""Mark words that describe a change in quantity or a relative level.

The component's high-impact examples are claims that a measure increased,
decreased, or was higher or lower. This predicts from word meaning, not from
the numerical values being discussed.
"""
READS = ()

STEMS = (
    "increas", "decreas", "reduc", "declin", "higher", "lower",
    "greater", "less", "quantit", "amount", "level", "moderate", "high",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc and token and token[0].isalpha():
        previous = carry[1]

    pieces = [part for part in token.replace("\ufffd", " ").split()]
    words = []
    for piece in pieces:
        letters = "".join(ch for ch in piece if ch.isalpha())
        if letters:
            words.append(letters)
    if previous and words:
        words[0] = previous + words[0]

    active = any(word.startswith(STEMS) for word in words)
    trailing = ""
    for ch in reversed(token):
        if ch.isalpha():
            trailing = ch + trailing
        else:
            break
    if previous and token and token[0].isalpha() and token.isalpha():
        trailing = previous + trailing
    return (doc, trailing), (0.24 if active else 0.0)

programs.sol:
"""A readable approximation to word and phrase continuation strength.

Long letter fragments following letters get positive scores, especially
grammatical endings and fragments following long stems. Word starts and CamelCase
identifier stems stay near zero. The same continuation idea covers conventional
place names, a few fixed phrases, and dotted output/abbreviation notation.
All memory is cleared at document boundaries; only the last token is retained.
"""
import re

READS = ()

COMMON_ENDINGS = {
    's': 0.13, 'es': 0.12, 'er': 0.17, 'ed': 0.56,
    'ly': 0.44, 'al': 0.19, 'ic': 0.24, 'ia': 0.22,
    'ian': 0.41, 'ion': 0.45, 'ize': 0.28, 'ise': 0.17,
    'ally': 0.54,
}
NOUN_ENDINGS = (
    'ation', 'ition', 'ution', 'sion', 'ment', 'ness', 'ity',
    'ology', 'ography', 'ification', 'ization', 'isation',
    'ion', 'ancy', 'ency',
)
ADJECTIVE_ENDINGS = (
    'able', 'ible', 'ical', 'istic', 'ative', 'ance', 'ified',
    'ious', 'ful', 'ial', 'ive', 'ous',
)
ADVERB_ENDINGS = ('ously', 'ively', 'fully', 'ably', 'ibly', 'ically', 'ally')

# Whole stems used in compound programming identifiers, rather than endings.
IDENTIFIER_STEMS = set('''
type name file data list node path test error value config string import
return console interface ignore const print builder style forms commons intel
'''.split())
COMPOUND_STEMS = {'bed', 'land', 'worth', 'problem'}

# Established two-word geographical names: first words -> second-word score.
PLACES = {
    'York': ({'New'}, 1.3), 'States': ({'United'}, 0.95),
    'Angeles': ({'Los'}, 1.9), 'Zealand': ({'New'}, 1.8),
    'Francisco': ({'San'}, 1.35), 'Kong': ({'Hong'}, 1.3),
    'Carolina': ({'North', 'South'}, 1.1),
    'Jersey': ({'New'}, 1.0), 'Diego': ({'San'}, 1.0),
    'Wales': ({'South'}, 1.25), 'Africa': ({'South', 'West', 'North'}, 0.7),
    'Dakota': ({'North', 'South'}, 0.7), 'Rico': ({'Puerto'}, 0.8),
    'Lanka': ({'Sri'}, 0.95), 'Hampshire': ({'New'}, 1.1),
}


def latin_continuation(text, stem_length, previous):
    word = text.lower()
    n = len(text)
    root = word
    if word.endswith('s') and n > 3 and not word.endswith(('ness', 'ous')):
        root = word[:-1]
    context = min(stem_length, 9) - 4
    slope = 0.08
    if word in COMMON_ENDINGS:
        value = COMMON_ENDINGS[word]
        if word in {'ed', 'ly'}:
            slope = 0.18
    elif root.endswith(ADVERB_ENDINGS):
        value = 1.13
    elif root.endswith(NOUN_ENDINGS):
        value = 0.91
    elif root.endswith(ADJECTIVE_ENDINGS):
        value = 0.9
    elif root.endswith('ing'):
        value = 0.66
    elif n > 3 and root.endswith('ed'):
        value = 0.81
    elif len(root) >= 4 and root.endswith(('er', 'or')):
        value = 0.44
    else:
        # Larger fragments carry a stronger within-word signal.
        value = (-0.05, -0.04, 0.22, 0.49, 0.63, 0.87)[min(n, 6) - 1]
        value += 0.05 * max(0, min(n, 9) - 6)
        slope = 0.01 if n <= 2 else 0.08 if n <= 4 else 0.02
    value += slope * context
    if n >= 5 and word[0] in 'aeiou':
        value += 0.22
    if text.isupper() and n >= 3:
        value += 0.19
    if previous.strip().istitle():
        value += 0.03
    if root != word:
        value += 0.05
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    value = -0.005
    word = text.lower()
    if text.isalpha() and previous[-1:].isalpha():
        n = len(text)
        stem_length = len(re.search(r'[^\W\d_]+$', previous).group())
        if n > 1 and (text.istitle() or not (text.islower() or text.isupper())):
            value = 0.0
        elif word in IDENTIFIER_STEMS or word in COMPOUND_STEMS:
            value = 0.0
        elif text.isascii():
            value = latin_continuation(text, stem_length, previous)
        elif all('\u0400' <= c <= '\u052f' for c in text):
            value = min(0.65, -0.07 + 0.24 * max(0, n - 2))
            if word.endswith(('ение', 'ения', 'ении', 'ания', 'ость', 'ости')):
                value = 0.87
            if word in {'ный', 'ной', 'ные', 'ных', 'ного', 'ная'}:
                value = -0.18
            value += 0.035 * (min(stem_length, 9) - 3)
        elif all('a' <= c <= 'z' or '\u00c0' <= c <= '\u024f' for c in word):
            value = min(1.0, -0.07 + 0.27 * max(0, n - 1))
        else:
            value = 0.0
        if previous.strip() in {'math', 'text'} and word in {'bb', 'bf', 'rm', 'it'}:
            value = 0.75  # LaTeX font commands.
    elif text.startswith(' '):
        last_word = re.search(r'[^\W\d_]+$', previous)
        prior = last_word.group() if last_word else ''
        current = text.strip()
        if current in PLACES and prior in PLACES[current][0]:
            value = PLACES[current][1]
        elif current == 'least':
            value = 1.04 if prior.lower() == 'at' else 0.2
        elif current == 'able':
            value = 0.66 if prior.lower() in {'be', 'being'} else 0.33
        elif current == 'respect':
            value = 0.65 if prior.lower() == 'with' else 0.2
        elif current == 'deviation':
            value = 0.8 if prior.lower() == 'standard' else 0.1
        elif current in {'sure', 'accordance', 'behalf'}:
            value = 0.5
    elif word in {'.log', '.println', '.sprintf', '.out'}:
        value = 0.8
    elif text in {'.e', '.g'}:
        value = 0.55
    return (doc, text), float(value)

programs.luna:
"""Approximate a sparse detector for long or morphologically marked words.

It tracks a word across token pieces and predicts a small positive response for
long forms and a few familiar derivational endings.
"""

READS = ()

ENDINGS = (
    "ation", "ations", "ition", "itions", "ization", "isation",
    "istical", "istic", "istics", "ical", "ically", "ity", "ities",
    "ive", "ives", "ous", "ously", "ance", "ances", "ence", "ences",
    "ment", "ments", "ness", "less", "ful", "ism", "isms", "ist",
    "ists", "ize", "ise", "able", "ible", "ary", "ory", "ology",
    "ing", "ings", "ed", "ers", "ors", "tion", "tions",
    "ость", "ости", "ение", "ения", "ении", "ировать", "тор",
    "keit", "heit", "lich", "isch", "ung", "iert", "ères",
)


def _letters(text):
    return "".join(ch for ch in text if ch.isalpha())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = "" if carry is None or carry[0] != doc else carry[1]
    piece = prefix.token_strings[-1]
    last_word = ""
    for ch in piece:
        if ch.isalpha() or ch.isdigit():
            word += ch
        elif ch in "'’ʼ‐‑‒–—-" and word:
            continue
        elif ch != "\ufffd":
            if word:
                last_word = word
            word = ""

    current = word or last_word
    letters = _letters(current)
    tail = _letters(piece)
    score = 0.0
    if tail and letters:
        lower = letters.lower()
        if len(letters) >= 10:
            score = 0.12
        if len(letters) >= 7 and any(lower.endswith(end) for end in ENDINGS):
            score = max(score, 0.14)
        if current[:1].isupper() and len(letters) >= 7:
            score = max(score, 0.12)

    return (doc, word), float(score)

"""Recognize 'with' and its Italian/Spanish counterpart 'con'."""

READS = ()


def step(carry, prefix, upstream):
    """The component most strongly responds to 'with', and sometimes 'con'."""
    word = prefix.token_strings[-1].strip().casefold()
    if word == "with":
        return None, 0.85
    if word == "con":
        return None, 0.4
    return None, 0.0

programs.sol:
"""Local spelling cues for a negative 'at'-stem response.

Short cat/pat/bat stems are strongest; longer words attenuate the cue.
Several common word families are exceptions. Unspaced at- suffixes use
only the preceding token's trailing word-fragment length, not full context.
Wait, Chinese cat characters, and Cyrillic ат have explicit rules.
Small positive signals and individual-token quirks are mostly left out.
"""
import math
import re

READS = ()
AT_ONSETS = {
    'c': 2.25, 'p': 1.8, 'b': 1.15, 'r': 0.8, 'k': 1.1,
    'l': 0.55, 'n': 0.7, 'f': 0.5, 'm': 0.3, 's': 0.3,
    'h': 0.22, 'w': 0.3, 't': 0.4,
}
QUIET_FAMILIES = (
    'path', 'patt', 'patch', 'water', 'watch', 'late', 'math',
    'mater', 'matr', 'match', 'rather', 'attr',
)


def response(token, previous):
    word = token.strip().lower().lstrip('_./(')
    n = len(word)
    if word.startswith('wait'):
        return -0.48 if token.lstrip().startswith('Wait') else -0.34
    if word in ('猫', '貓'):
        return -2.2
    if word.startswith(QUIET_FAMILIES):
        return 0.0
    if word.startswith('at') and word.isalpha():
        if word == 'at' and (token[:1].isspace() or token == 'At'):
            return 0.0
        if token[:1].isspace():
            return -0.25
        match = re.search(r'[^\W\d_]+$', previous)
        length = len(match[0]) if match else 0
        if word.startswith('ativ'):
            value = 0.0
        elif word.startswith('ation'):
            value = -0.2
        elif word in ('ate', 'ates', 'ated', 'ating'):
            value = -0.34
        elif word.startswith(('ath', 'atur', 'atri', 'atam')):
            value = -0.13
        elif word == 'at' or word.startswith(('ator', 'att')):
            value = -0.43
        elif word in ('atas', 'atos'):
            value = -1.5
        else:
            value = -0.68
        length_effect = 0.10 * (min(length, 7) - 3)
        return value + length_effect + (0.4 if not length else 0)
    if n >= 3 and word[1:3] == 'at' and word[0] in AT_ONSETS:
        strength = AT_ONSETS[word[0]]
        if n == 3 or (n == 4 and word.endswith('s')):
            return -strength
        if word.startswith(('cation', 'cattle', 'cathy', 'pati')):
            return -0.2
        if word.startswith(('categ', 'ratio', 'ration', 'rating', 'latin')):
            return -0.65
        if word.startswith('catch'):
            return -0.6 * 5 / n
        if word in ('rate', 'rates'):
            return -0.14 if token[:1].isspace() else -0.5
        if word[0] == 'n' or word.startswith(
            ('bathroom', 'battalion', 'battlefield')
        ):
            return -0.1
        return -strength * math.exp(-0.23 * (n - 3))
    if word.startswith(('eat', 'beat')):
        return -0.38 if word.startswith('eat') else -0.65
    if word.startswith(('аться', 'ать')):
        return 0.18
    if word.startswith('ат') and not word.startswith(('атор', 'аци')):
        return -0.8
    if word.startswith(('кат', 'пат', 'бат', 'рат', 'лат', 'мат')):
        return -0.8 * math.exp(-0.25 * max(0, n - 3))
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == document
    previous = carry[1] if same_document else ''
    token = prefix.token_strings[-1]
    return (document, token), float(response(token, previous))

programs.luna:
"""Estimate the component from a spelling fragment in the current token piece.

Its clearest recurring responses are negative on pieces containing "cat" and
on the word "wait"; weaker negative responses occur on other spellings with
"at", including the Cyrillic pair "ат". These are token spellings, not
whole-word meanings, so the rule also catches word fragments.
"""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()
    if "wait" in token:
        value = -0.43
    elif "cat" in token:
        value = -0.26
    elif "ат" in token:
        value = -0.32
    elif token.startswith("at"):
        value = -0.17
    elif token.endswith("at"):
        value = -0.08
    elif "at" in token:
        value = -0.07
    else:
        value = 0.0
    return None, value

programs.sol:
"""A sparse lexical approximation to the making/production response.

Make, makes, making and made get the strongest English verb responses.
Related manufacturing, machinery, process and material words get smaller
responses. Chinese production terms and a Russian production root are also
recognized. Manufacturing/production/machining immediately before process,
line or tool strengthens that noun. The previous-token state resets at each
new document. All other tokens return zero; finer context is not modeled.
"""
READS = ()


def lexical_score(token):
    word = token.strip().lower().lstrip('._(')
    if word in {'make', 'makes', 'making', 'made'}:
        value = {'make': 0.94, 'makes': 0.88,
                 'making': 1.01, 'made': 0.70}[word]
        if not token.startswith(' ') or token.strip()[0].isupper():
            value -= 0.09
        return value
    if word in {'maker', 'makers'}:
        return 0.4
    if word in {
        'manufacture', 'manufacturing', 'manufact', 'machining'
    }:
        return 1.0
    if word.startswith('manufactur'):
        return 0.65
    if word in {'factory', 'factories', 'industrial'}:
        return 0.6
    if word == 'production':
        return 0.55
    if word == 'producing':
        return 0.4
    if word in {'produce', 'produced', 'produces', 'industries'}:
        return 0.25
    if word in {
        'machine', 'machines', 'machinery', 'robot', 'robots'
    }:
        return 0.4
    if word in {
        'molding', 'moulding', 'milling', 'fabricated', 'spindle', 'cnc'
    }:
        return 0.75
    if word in {'metal', 'metallic', 'fabric'}:
        return 0.45
    if word in {
        'forming', 'rolling', 'mold', 'mould', 'assembly', 'belt'
    }:
        return 0.3
    if word in {
        'steel', 'aluminum', 'plastic', 'processing', 'processed'
    }:
        return 0.2
    if word in {'process', 'processes', 'parts', 'industry', 'goods'}:
        return 0.15
    if word in {'line', 'lines', 'part'}:
        return 0.08
    if any(root in word for root in ('工厂', '工廠')):
        return 1.2
    if any(root in word for root in ('生产', '生產', '制造', '製造', '加工')):
        return 0.9
    if word in {'产业', '產業', '产', '產', '製'}:
        return 0.5
    if word in {'机器', '機器', '机械', '機械', '造', '工'}:
        return 0.35
    if word in {'机', '機', '线', '線'}:
        return 0.18
    if word.startswith('производ'):
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    word = token.strip().lower()
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_score(token)
    if previous in {'manufacturing', 'production', 'machining'}:
        if word in {'process', 'processes', 'line', 'lines', 'tool', 'tools'}:
            value += 1.0
    return (doc, word), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4871 - the "make / manufacture" word detector.

What it does: this component fires on the word "make" (and its forms) and on
manufacturing vocabulary: "make", "making", "makes", "manufacture(d/s/ing)",
"production", "industrial", "factory", "machine", Chinese 生产 / 制造 / 工厂.
It fires weakly on other production-related words, and is about zero on
everything else. It ignores context: the same word gets the same value anywhere.

Predicted activation, per token:
  1.0  make / making / makes, manufacture-family words, 生产 / 制造 / 工厂
  0.7  made (the past participle, and manufactured / manufacturer)
  0.5  production, industrial, factory, machine(ry), mould / molding, metal, robot, fabric, ...
  0.2  produce / produced / process / parts / steel / goods
  0.0  everything else
Create, build, design and product stay near 0 and get 0 here.
"""

READS = ()

MAKE = {"make", "makes", "making", "manufacture", "manufactures", "manufacturing"}
MADE = {"made", "manufactured", "manufacturer", "fabrication"}
INDUSTRY = {"production", "producing", "industrial", "industries", "factory", "factories",
            "machine", "machines", "machinery", "machining", "mold", "mould", "molding",
            "metal", "robot", "fabric", "assembly"}
WEAK = {"produce", "produced", "producer", "process", "processed", "parts", "steel", "goods"}
CHINESE_MAKE = {"生产", "制造", "工厂"}


def word_of(token):
    """Lower-case word with surrounding spaces and punctuation removed (' Make' -> 'make')."""
    return token.strip().strip(".-_ ").lower()


def step(carry, prefix, upstream):
    """The activation at the newest token only; no state is carried between tokens."""
    token = prefix.token_strings[-1]
    word = word_of(token)
    if word in MAKE or token.strip() in CHINESE_MAKE:
        value = 1.0
    elif word in MADE:
        value = 0.7
    elif word in INDUSTRY:
        value = 0.5
    elif word in WEAK:
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

