"""Approximate a light-and-clarity feature from the token's words. It predicts
more for bright, dark, clear, and transparent words, and less for related
visual or crisp-description words; all other tokens get zero."""

import re

READS = ()

BRIGHT = ("bright",)
TRANSPARENT = ("transparent",)
DARK = ("dark",)
CLEAR = ("clear", "unclear", "clarity", "clarif", "visibility", "visible")
VISUAL = (
    "illumin", "lumin", "glow", "shin", "shadow", "white", "black",
    "fluoresc", "highlight", "flash", "shade", "sharp", "crisp", "smart",
    "clever", "intellect", "explicit", "brilliant", "glitter",
)
LIGHT_WORDS = frozenset((
    "light", "lights", "lighted", "lighting", "lighten", "lightness",
    "sun", "sunlight", "sunshine", "sunset", "sunrise", "sunlit",
    "moon", "moons", "moonlight", "daylight", "twilight", "flashlight",
))


def has_root(words, roots):
    return any(word.startswith(root) for word in words for root in roots)


def step(carry, prefix, upstream):
    words = re.findall(r"[^\W_]+", prefix.token_strings[-1].casefold())
    if has_root(words, BRIGHT):
        return None, 2.5
    if has_root(words, TRANSPARENT):
        return None, 1.1
    if has_root(words, DARK):
        return None, 0.9
    if has_root(words, CLEAR):
        return None, 0.55
    if any(word in LIGHT_WORDS for word in words) or has_root(words, VISUAL):
        return None, 0.35
    if any(ch in prefix.token_strings[-1] for ch in ("亮", "明", "光", "清", "白", "黑", "漂亮", "艳", "艷")):
        return None, 0.65
    return None, 0.0

programs.sol:
"""A small, approximate script-compatibility signal.

A running mixture of letter scripts makes Hangul positive in Korean text,
but Han characters and unusual punctuation negative there. Introducing Han
inside parentheses after other alphabetic text also gives a negative pulse.
Tool/thinking delimiters and selected grammatical word classes have their
own fitted offsets. Script history resets between documents. Most
token-specific activation variation is intentionally left unmodeled.
"""

READS = ()

# These tokens are incomplete UTF-8 starts, not activation lookup entries.
# Their spelling alone is U+FFFD; the IDs distinguish their byte families.
HAN_INITIALS = {160, 161, 162, 163, 164, 165,
                4891, 6567, 8908, 10236, 18137}
HANGUL_INITIALS = {166, 167, 168, 169, 3315, 5140, 8620, 10764}
WIDE_INITIALS = {171, 1540, 15393, 32495, 62823}
DELIMITERS = {
    '<tool_call>': 0.191, '</tool_call>': 0.327,
    '<tool_response>': 0.118, '</tool_response>': -0.071,
    '<think>': -0.079, '</think>': -0.066,
}
EMPHATIC_ADVERBS = {'really', 'quite', 'truly', 'especially', 'particularly'}
RESTRICTIVE_ADVERBS = {'just', 'only', 'merely', 'simply', 'solely',
                       'exactly', 'exclusively'}
MODAL_AUXILIARIES = {'can', 'could', 'may', 'might', 'must', 'will',
                     'would', 'shall', 'should'}


def is_han(c):
    n = ord(c)
    return 0x3400 <= n <= 0x4dbf or 0x4e00 <= n <= 0x9fff


def script(text, token_id):
    if token_id in HAN_INITIALS:
        return 'han'
    if token_id in HANGUL_INITIALS:
        return 'hangul'
    for c in text:
        n = ord(c)
        if is_han(c):
            return 'han'
        if 0xac00 <= n <= 0xd7a3:
            return 'hangul'
        if 0x3040 <= n <= 0x30ff:
            return 'kana'
        if 0x0600 <= n <= 0x06ff:
            return 'arabic'
        if c.isalpha():
            return 'other'
    return 'none'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        carry = (doc, 0.0, 0.0, 0.0, 'none', 0, False)
    _, korean, han, letters, previous, other_run, bracket = carry
    text = prefix.token_strings[-1]
    tid = prefix.token_ids[-1]
    kind = script(text, tid)
    completed_han = False
    if kind == 'none' and '�' in text:
        # A continuation-byte token can finish a character begun earlier.
        tail = prefix.text_prefixes[-1][-1:]
        completed_han = bool(tail) and is_han(tail)
        if completed_han:
            kind = 'han'
    k = korean / max(letters, 1.0)
    h = han / max(letters, 1.0)
    value = -0.00065762
    if text in DELIMITERS:
        value += 1.0525 * DELIMITERS[text]
    elif kind == 'hangul':
        value += -0.02843 + 0.09988 * k
        if text.startswith(' '):
            value -= 0.03765 * k
        if tid in HANGUL_INITIALS:
            value += 0.09988 * k
        if text == '인':                 # A copula/adnominal spelling.
            value += 0.20359 * k
        if text in {'는', '은'}:         # Topic-particle spellings.
            value += 0.07299 * k
        if text in {'가', '이'}:         # Subject-particle spellings.
            value += 0.03611 * k
    elif kind == 'han':
        value += 0.00678 - 0.56115 * k
        if previous != 'han' and not completed_han:
            value -= 0.32974 * k
        if previous == 'other' and h < 0.1 and other_run >= 4:
            value -= 0.08724
            if bracket and len(text.strip()) <= 1:
                value -= 0.22308
    elif kind == 'kana':
        value += 0.01540
    elif kind == 'arabic':
        value += 0.00308
        if text.startswith((' ال', ' لل', ' بال')) and len(text.strip()) <= 3:
            value += 0.07596            # Short article/preposition prefixes.
        if len(text.strip()) >= 6:
            value -= 0.02258
    elif kind == 'other':
        value -= 0.03098 * k + 0.00635 * h
    else:
        value -= 0.05099 * k
        if '�' in text:
            value += (0.25105 if text.startswith(' ') else 0.08368) * k
        if any(0xff01 <= ord(c) <= 0xffef for c in text):
            value -= 0.29349 * k
        if any(ord(c) > 127 and c != '�' and not c.isalnum() for c in text):
            value -= 0.11896 * k
        if text.startswith(' ') and text.strip() in {'“', '‘'}:
            value += 0.19946 * k
        if tid in WIDE_INITIALS:
            value = -0.44024 * k
    word = text.strip().lower()
    if word in EMPHATIC_ADVERBS:
        value += 0.05874
    elif word in RESTRICTIVE_ADVERBS:
        value -= 0.02153
    elif word in MODAL_AUXILIARIES:
        value -= 0.00969
    if kind != 'none' and text not in DELIMITERS:
        previous = kind
        letters = 0.97 * letters + 1.0
        korean = 0.97 * korean + (kind == 'hangul')
        han = 0.97 * han + (kind == 'han')
    if kind == 'han':
        other_run = 0
    elif kind == 'other':
        other_run += 1
    bracket = text.rstrip().endswith(('(', '[', ':'))
    return (doc, korean, han, letters, previous, other_run, bracket), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4874 -- a weak, mostly token-level feature.

What it does, in plain terms:
  * Chat/tool-markup tokens get a fixed value. The opening and closing tool-call tags
    (<tool_call>, </tool_call>) and the tool-response opener (<tool_response>) push the
    activation positive; the closing tool-response tag (</tool_response>) pushes it slightly
    negative.
  * Other tokens are scored by script. Hangul syllables are the most positive (about +0.07),
    then kana, CJK ideographs, other non-ASCII letters, and U+FFFD fragments (all small
    positive). Ordinary ASCII text, which is most tokens, is predicted at 0.

The component's activation is mostly set by which token it is, but not by a concept that
fits in a few lines. These rules capture only the largest concept-shaped pieces; they explain
a few percent of its variance, not most of it.
"""

READS = ()

TOOL_TAG_VALUES = {
    "<tool_call>": 0.19,
    "</tool_call>": 0.33,
    "<tool_response>": 0.12,
    "</tool_response>": -0.07,
}


def script_value(text):
    """Mean activation for a token's script, as measured on training text."""
    if any("가" <= c <= "힣" for c in text):
        return 0.07  # Hangul syllables
    if any("぀" <= c <= "ヿ" for c in text):
        return 0.013  # hiragana / katakana
    if any("一" <= c <= "鿿" for c in text):
        return 0.008  # CJK ideographs
    if "�" in text:
        return 0.01  # a fragment of a multi-byte character
    if any(ord(c) > 127 and c.isalpha() for c in text):
        return 0.003  # other non-ASCII letters
    return 0.0  # ASCII text, digits, punctuation


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TOOL_TAG_VALUES:
        return carry, float(TOOL_TAG_VALUES[token])
    return carry, float(script_value(token))

