programs.sol:
"""Recognize a-initial spelling pieces after consonant-only fragments.

The largest predictions go to unspaced a-pieces after short consonant-only
fragments, especially fragments preceded by whitespace. Token length,
vowel count, spacing, and capitals adjust the response. Accented Latin a, Cyrillic а and Arabic ا are included.
No lexical lookup is used: this captures a broad pattern, not word-specific
preferences.
"""
import re
import unicodedata

READS = ()
VOWELS = frozenset('aeiouаеиоуыэюяاوي')


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    carry = (doc, token)
    word = plain(token.strip())
    if not word or word[0] not in 'aаا':
        return carry, 0.0
    length = len(word)
    tail = re.search(r'[^\W\d_]+$', plain(previous))
    tail = tail[0] if tail else ''
    onset = bool(tail) and not any(c in VOWELS for c in tail)
    if not onset:
        return carry, 0.065 if length == 4 else 0.0
    if not token[0].isalpha():
        return carry, 0.04
    if previous[:1].isspace():
        if len(tail) == 1:
            value = 0.75 if length == 4 else 0.63 if length == 3 else 0.49
        else:
            value = 0.45 if sum(c in VOWELS for c in word) >= 2 else 0.28
    elif len(tail) == 1 and any(c.isupper() for c in previous):
        value = 0.43
    else:
        value = 0.38 if length == 4 else 0.22
    return carry, value

"""A spelling-based -er detector, with a weaker response to -or and -ar.

The response is negative. Short word fragments amplify -er; long spellings
and plurals dilute it. Comparatives, relative positions and related prefixes
also amplify it. Common linking words, thinking/reply verbs and month names
are weak exceptions. Cyrillic ер and water vocabulary extend the main rule.
"""
import re

READS = ()
COMPARATIVES = set('''better higher lower upper larger smaller greater longer
shorter older younger earlier later faster slower closer deeper simpler
easier harder further'''.split())
RELATIONS = set('upper lower inner outer latter former'.split())
PREFIXES_AND_ROOTS = set('inter super hyper cyber unter iter'.split())
FUNCTION_WORDS = set('over per der er her'.split())
DISCOURSE = set('however whenever wherever moreover together'.split())
THINKING_OR_REPLY = set('consider remember answer'.split())
MONTHS = set('september october november december'.split())
WATER = set('water hydro hydrogen moisture 水'.split())


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    attached = (carry is not None and carry[0] == doc
                and carry[1] and raw[:1].isalpha())
    carry = (doc, bool(raw) and raw[-1].isalpha())
    word = re.sub(r'^[^\w]+', '', raw.strip().lower())
    size = len(word)
    value = -0.005
    if re.search(r'ers?$', word) and not word.endswith(('ear', 'ears')):
        value += -1.61 + 0.09 * min(size, 12)
        if size <= 3:
            value += 0.27
        if attached and size <= 5:
            value -= 0.61
        if word.endswith('ers'):
            value += 0.30
        if re.search(r'(.)\1ers?$', word):
            value -= 0.26
        if word in FUNCTION_WORDS:
            value += 0.53
        if word in DISCOURSE or word in THINKING_OR_REPLY:
            value += 0.85
        if word in MONTHS:
            value += 0.90
        if word in RELATIONS:
            value -= 0.70
        if word in COMPARATIVES:
            value -= 0.25
        if word in PREFIXES_AND_ROOTS:
            value -= 0.51
    elif re.search(r'ors?$', word) and size > 3:
        value -= 0.52
    elif re.search(r'ars?$', word) and not word.endswith(('ear', 'ears')):
        value -= 0.28
    elif re.search(r'[iu]rs?$', word) and word not in {'our', 'your', 'their'}:
        value -= 0.19
    elif re.search(r'ер(?:ы|а|ов)?$', word):
        value -= 1.27
    if word in WATER:
        value -= 0.60
    return carry, float(value)

