"""Lexical detector for const-like spellings and keep/guard characters.

`const` gives a large negative response. Spelling, document start, and the
preceding qualifier/parameter context set its strength. Capitalized forms
and related word families respond more weakly. 守 (keep/guard) is another
strong trigger, weaker in compounds; 常 (constant) and the Russian root
постоян- have small responses. Other tokens get zero. This is a lexical
approximation, not a general semantic test for constancy.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    previous = '' if new_doc else carry[1]
    word = token.strip().lstrip('(_,.:')
    lower = word.lower()
    value = 0.0

    if lower == 'const':
        if word == 'CONST':
            value = -3.5
        elif word == 'Const':
            value = -3.8
        elif new_doc:
            value = -9.5
        elif token.startswith('\t'):
            value = -4.9
        elif token.startswith('('):
            value = -5.1
        elif previous.rstrip().endswith((')', ',', '(', '::')):
            value = -6.6
        elif previous.strip() in {'extern', 'static'}:
            value = -6.7
        elif previous.isspace() or '\n' in previous:
            value = -5.4
        else:
            value = -5.8
    elif word == '守':
        value = -7.9
    elif '守' in word:
        value = -2.4
    elif word == '常':
        value = -0.6
    elif lower.startswith('постоян'):
        value = -1.0
    elif lower == 'constit':
        value = -1.8
    elif lower.startswith(('constituenc', 'constell')):
        value = -1.65
    elif lower.startswith('constitution'):
        value = -0.75
    elif lower.startswith('constituent'):
        value = -1.05
    elif lower.startswith('constant'):
        value = -0.65 if lower.endswith('s') else -1.3
    elif lower.startswith('conserv'):
        value = -1.5 if lower.startswith('conservativ') else -0.85

    return (doc, token), value

