"""Component layers.0.mlp.down_proj:4880: an "indefinite quantifier" detector.

The component is almost silent except on the word "some". When the current token is
"some" (any capitalisation, with or without its leading space) it writes a large
negative value, about -7. Its translations ("einige", "algunos", "一些", ...) get a
smaller negative value, roughly -2 to -5. Words built on "some" ("someone",
"something", "sometimes", ...) and other quantifying determiners ("these", "those",
"many", "several", "certain", "few") get a small negative value, about -1.

The program only reads the token being predicted, with no memory across positions;
the activation hardly depends on the surrounding context.
"""

READS = ()

SOME = {"some"}

SOME_COMPOUNDS = {"someone", "something", "somehow", "sometimes", "somewhat", "somewhere"}

FEW_QUANTIFIERS = {"these", "those", "many", "several", "certain", "few"}

SOME_TRANSLATIONS = {
    "einige", "algunos", "algunas", "algumas", "algum", "alguns", "beberapa", "alcuni",
    "niektóre", "niekt", "некоторые", "некоторых", "بعض", "일부", "一些", "有些", "某些",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SOME:
        value = -7.0
    elif word in SOME_TRANSLATIONS:
        value = -3.0
    elif word in SOME_COMPOUNDS:
        value = -1.0
    elif word in FEW_QUANTIFIERS:
        value = -0.8
    else:
        value = 0.0
    return carry, value

