READS = ()

# 'aspect' itself, and its Chinese counterpart 方面 (and compounds such as 一方面, 这方面).
ASPECT = {"aspect", "aspects", "pects"}
# Other words for a dimension, facet or field: strong-ish.
DIMENSION = {"dimension", "dimensions", "facet", "facets", "层面", "领域", "领域的", "全面",
             "全方位", "角度", "阶段"}
# Weaker: 'area(s)', 'side(s)', 'regarding', 'overall', 'basically', Japanese/Chinese 'about'.
WEAK = {"area", "areas", "sides", "regarding", "overall", "basically", "面", "について",
        "に関して", "总体", "整体"}


def _word(s):
    return s.strip().lower()


