"""Approximate a detector for 'an' in short token fragments, not meanings.

Whitespace, case and token length control the response. Grammatical
words, demonyms, and productive -man/-ian endings receive adjustments.
Related extensions and Cyrillic/Arabic spellings are recognized, as
are Japanese na/an forms and Korean syllables with vowel a and final n.
Only an/can/than use the previous token; this state resets per document.
Unrecognized tokens get zero. Broader context and lexical quirks are
not modeled.
"""
READS = ()

# Strengths for token lengths 3, 4, 5, 6, 7, and 8 or more characters.
FRAGMENT = (2.6, 2.15, 1.4, 0.6, 0.45, 0.35)
CAPITALIZED = (2.5, 2.25, 1.55, 1.0, 0.6, 0.35)
SPACED_WORD = (1.9, 1.55, 1.1, 0.55, 0.55, 0.5)
DEMONYMS = {'american', 'european', 'russian', 'italian', 'african',
            'indian', 'australian', 'norwegian'}


def spelling_value(token):
    word = token.strip()
    s = word.lower()
    spaced = token[:1].isspace()
    if s.endswith('ан'):
        return 1.1 if spaced else 1.95
    if s.endswith('ان'):
        return 1.4
    if s.endswith('ían'):
        return 0.45  # Spanish conjugation ending.
    if s.endswith(('ани', 'ана', 'án', 'àn', 'än')):
        return 0.75
    if s.endswith('な'):
