        if syllable // 28 % 21 == 0 and syllable % 28 == 4:
            return 0.45  # Hangul vowel a followed by final n.
    if s in {'an', 'can'}:
        if word.istitle():
            return 1.45
        if spaced:
            return 1.22
        return 2.45 if s == 'an' else 1.5
    if s in DEMONYMS or s == 'began':
        return 0.15
    if s == 'january':
