    if s == 'jan' and (spaced or word.istitle()):
        return 1.45
    if s in {'organ', 'melan'}:
        return 2.35  # Short anatomical and pigment roots.
    if s.endswith('an'):
        if s.endswith('man'):
            return 0.63 if spaced else 1.24
        if s == 'ian':
            return 3.0 if word.istitle() else 1.0
        if s.endswith('ian'):
            return 0.46 if spaced else 1.0
        if s.endswith(('ean', 'oan')):
            return 0.24 if spaced else 0.63
        if s in {'plan', 'span'}:
            return 0.8 if s == 'plan' and spaced else 1.15
        if s in {'kan', 'dan', 'ran'} and spaced and word.islower():
            return 1.2
        table = FRAGMENT
        if word.istitle():
            table = CAPITALIZED
        elif spaced:
            table = SPACED_WORD
        return table[min(5, max(0, len(word) - 3))]
    if s in {'dans', 'sans', 'trans'}:
        return 0.2  # Spatial prepositions and the trans- prefix.
    if s.endswith('ans'):
        return 0.65 * spelling_value(token[:-1])
    if s.endswith(('ana', 'ane', 'ani', 'ano', 'ann', 'anic', 'anning', 'anned')):
        return 1.1 if word.istitle() and len(word) <= 5 else 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = spelling_value(token)
    if word == 'than':
        if previous in {'more', 'less', 'greater', 'fewer'}:
            value = 0.04
        elif previous in {'larger', 'bigger', 'smaller', 'rather'}:
            value = 0.25
        elif previous in {'better', 'lower', 'longer', 'other'}:
            value = 0.65
        else:
            value = 1.0
    elif word == 'can' and token.startswith(' '):
        if previous in {'i', 'you', 'we', 'he', 'she'}:
            value = 1.06
    elif word == 'an' and token.startswith(' '):
        if previous in {'have', 'has', 'had', 'was', 'be', 'as', 'like'}:
            value = 1.0
    return (doc, word), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4882 - the "-an" sound detector.

The component reads the current token and fires when the token's letters end in the
sound "an" (also Cyrillic "ан"). How strongly depends on what the "an" is part of:

- a word-piece with no leading space, such as "jan", "han", "elan", "ogan": strongest,
  about 2 when the stem before "an" is 3 letters or fewer, about 0.5 for a 4-5 letter
  stem, about 0.1 for longer;
- the bare words "an", "can", "ans": about 1.3 with a leading space, 2 without;
- a short word with a leading space: about 1.4 if capitalised (" Dan", " Van", " Ryan",
  " Khan"), about 1.0 if lowercase (" tan", " scan"); about 0.5 for a 4-5 letter stem and
  0.25 for longer words;
- everyday English words and -ian/-ean words that merely end in "an" (man, mean, than,
  began, clean, human, woman, American, Italian) give about 0.35.

An "an" inside a token (anything, Mandarin, understand) is off. Everything else is 0.

The program is stateless: each prediction reads only the newest token's text.
"""

READS = ()

# Everyday English words ending in "an" that do not fire much.
PLAIN_AN_WORDS = {"man", "mean", "than", "began", "clean", "human", "woman", "median"}


def _letters(text):
    """The token's letters, lowercased: " Dan" -> "dan", "AN" -> "an"."""
    return "".join(ch for ch in text.lower() if ch.isalpha())


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = _letters(raw)
    if not word.endswith(("an", "ан")):
        return carry, 0.0
    if word in PLAIN_AN_WORDS or word.endswith(("ian", "ean")):
        return carry, 0.35
    if word in ("ans", "an", "can"):
        return carry, 1.3 if raw.startswith(" ") else 2.0
    stem = len(word) - 2  # letters before the final "an"
    if not raw.startswith(" "):
        return carry, 2.0 if stem <= 3 else (0.5 if stem <= 5 else 0.1)
    if stem <= 3:
        return carry, 1.4 if raw.strip()[:1].isupper() else 1.0
    return carry, 0.5 if stem <= 5 else 0.25

programs.sol:
"""Document-opening syntax, doubled escapes, and ignore-file names.

Approximate the strong responses with familiar text patterns: document-opening
headings, title labels, imports/comments and English sentence openers are
negative. Doubled backslashes and repeated escaped tabs are also negative;
ignore-file suffixes are positive. Short word parts ending in t (or Cyrillic т)
following another t-ending part receive a weaker negative correction. Chat
wrappers and document position supply small biases. Ordinary word-specific
fluctuations are not modeled.
"""

READS = ()

PRONOUNS = frozenset('I We You He She It They This That There'.split())
PREPOSITIONS = frozenset('In On At For From To With By As'.split())
QUESTIONS = frozenset('What Who When Where Why How Which'.split())
IMPORTS = frozenset(('import', 'package', 'from', '#include'))


def opening_value(s):
    # Distinguish bare words from space-prefixed opening tokens.
    if s == 'Title':
        return -2.558
    if s.strip('#') == '' and s:
        return -1.60
    if s in IMPORTS:
        return -1.30
    if s == 'using':
        return -0.64
    if s.startswith(('//', '/*', '#!', '"""', "'''")):
        return -0.82
    if s.strip() == 'The':
        return -1.375 if s == 'The' else -0.755
    if s.strip() == 'the':
        return -0.633 if s == 'the' else -0.339
    if s == 'A':
        return -0.476
    if s in ('He', 'She'):
        return -0.20
    if s in PRONOUNS:
        return -0.637
    if s in PREPOSITIONS:
        return -0.468
    if s in QUESTIONS:
        return -1.061
    if s.startswith('<|'):
        return 0.094 if s == '<|im_start|>' else 0.0
    if s.isspace():
        return -0.146
    if s.strip().isdigit():
        return -0.123
    if s.isascii() and s.isalpha():
        return -0.22
    if s.startswith(' ') and s.strip().isascii() and s.strip().isalpha():
        return -0.167
    return -0.14


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, tail = 0, ''
    else:
        _, position, tail = carry
    if position == 0:
        value = opening_value(s)
    else:
        value = -0.033 / position ** 0.75 + 0.000007 * position
    if position > 0:
        # Word parts spanning a repeated t are weak negative triggers too.
        last = tail[-1:].lower()
        if (last in ('t', 'т') and s.isalpha() and len(s) <= 5
                and s[-1:].lower() == last):
            value -= 0.20 / max(1, len(s) - 1)
        if s == '\\t' and tail.endswith('\\t'):
            value = -0.11
        if s in ('<think>', '<tool_call>'):
            value = -0.13
        if s == '</think>':
            value = 0.135
    if '\\\\' in s:
        # Three-slash tokens have a weaker response than two or four.
        if '\\\\\\\\' in s:
            value = -1.14
        elif '\\\\\\' in s:
            value = -0.48
        else:
            value = -0.94 if s.startswith(' ') else -1.00
    if position > 0 and s.strip().lower() == 'ignore':
        if tail.endswith('git'):
            value = 0.89
        elif tail.endswith('docker'):
            value = 0.36
        else:
            value = 0.23 if s.strip() == 'ignore' else 0.18
    return (doc, position + 1, (tail + s)[-20:]), float(value)

"""A c/h-centered spelling signal across adjacent token boundaries.

Short consonant fragments after c receive negative values, strongest for
h/k/j/z. Spaces weaken this effect; long preceding tokens weaken c+h.
Short h-initial fragments have separate preceding-letter and case effects.
These rules approximate the large spelling responses, not all the small
lexical variations. Normalize character width and reset at document changes.
"""
import unicodedata

READS: tuple[str, ...] = ()
VOWEL_LETTERS = frozenset("aeiouy")


def after_c(text, previous):
    word = text.lstrip()
    first = word[:1].lower()
    n = len(word)
    spaced = len(word) != len(text)
    if first == 'h':
        if spaced:
            return -0.98 if n == 1 else -0.14
        if len(previous.strip()) > 4:
            return -0.56
        return -1.79 if n <= 2 else -1.13
    if first in ('k', 'j', 'z'):
        if spaced:
            return -0.13
        if n <= 2:
            second_is_vowel = word[1:2].lower() in VOWEL_LETTERS
            return -1.63 if second_is_vowel else -1.14
        return -0.92 if n == 3 else -0.25
    if first in ('b', 'g', 'v'):
        if spaced:
            return -0.05
        return -0.65 if n <= 2 else -0.13
    if first and first in 'dlmnpqrstfwx':
        if spaced:
            return 0.04
        return -0.17 if n <= 2 else -0.07
    if first.isdigit():
        return -0.06
    return 0.054


def initial_h(text, previous):
    n = len(text)
    end = previous[-1:].lower()
    base = unicodedata.normalize('NFD', end)[:1]
    if end == 'k':
        return -0.40 if n <= 3 else -0.11
    if base and base in 'iuy':
        return 0.42 if n <= 3 else 0.10
    if end == 'l':
        return 0.80 if text.isupper() else 0.20
    if base and base in 'ao':
        return 0.18
    if end and end in 'mfvq':
        return 0.26
    if n == 1:
        return -0.27 if end in ('s', 'g') else -0.01
    if n == 2:
        if end == 'g':
            return -0.12
        return 0.26 if text.isupper() else 0.09
    return 0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = unicodedata.normalize("NFKC", prefix.token_strings[-1])
    if previous[-1:].lower() == 'c':
        value = after_c(text, previous)
    elif text[:1].lower() == 'h':
        value = initial_h(text, previous)
    else:
        value = -0.001
    return (doc, text), float(value)

