programs.sol:
"""A sparse spelling-and-formatting approximation.

Positive peaks mark internal 'ier' clusters and several vowel-led word
endings, especially after short fragments. F-ligatures, selected remnant
spellings, and split signi-/identi-/speci- prefixes receive larger scores.
These are literal spelling matches, not a general corruption detector.
Tabs and form feeds are positive; an isolated carriage return depresses
its own and the following token's score. Other unmatched cases are zero.
Only the previous token is carried, reset at document boundaries. The
approximation deliberately omits diffuse, word-specific variation.
"""
READS = ()

IE_ENDINGS = {'ied', 'ient', 'ien'}
IC_DERIVATIONS = {'icate', 'ication', 'icular'}
IC_ENDINGS = {'ic', 'ical', 'ically'}
EC_FRAGMENTS = {'ec', 'ect', 'ective', 'ection'}
E_INFLECTIONS = {'er', 'ers', 'ed'}
F_LIGATURES = set('ﬀﬁﬂﬃﬄ')
# Spellings left behind when fi/fl/ff disappear in extracted text.
LIGATURE_REMNANTS = {'rst', 'nal', 'cant', 'cult', 'eld', 'uid'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token == 'ier':
        value = 0.51
    elif token == 'iers':
        value = 0.26
    elif token in IE_ENDINGS:
        value = 0.17
    elif token in IC_DERIVATIONS:
        value = 0.26
    elif token in IC_ENDINGS:
        value = 0.08
    elif token in EC_FRAGMENTS:
        value = 0.23
    elif token in E_INFLECTIONS:
        value = 0.05
    if value and previous.strip().isalpha() and len(previous.strip()) <= 2:
        value += 0.06

    if token == 'cient':
        value = 0.50
    if any(c in F_LIGATURES for c in token):
        value = 0.90
        if 'ﬂ' in token:
            value = 0.60
        elif 'ﬃ' in token:
            value = 1.30
    elif token.strip() in LIGATURE_REMNANTS:
        if '\ufffd' in previous or token.startswith(' '):
            value = 0.55
    if token == 'i' and previous.strip().lower() in {'sign', 'ident', 'spec'}:
        value = 0.85
    if token.strip() == 'cant' and previous == 'i':
        value = 1.50

    if token == '\r':
        value = -0.09
    elif token and token.strip('\t') == '':
        value = 0.025
    elif token == '\t\n':
        value = 0.06
    elif token == '\f':
        value = 0.21
    if previous == '\r':
        value -= 0.07
    return (doc, token), float(value)

