"""A token-local detector for short 'un' spellings, not negation in general.

Spacing, capitalization, and following letters adjust the response. Longer
continuations usually weaken it: 'fun', 'run', and 'Jun' fire, while most
long words do not. Smaller responses cover 'non', selected related script
spellings, and running/hunting/firearm words. Other tokens predict zero.
This leaves contextual variation and diffuse background responses unmodeled.
"""

READS = ()


def response(token):
    spaced = token[:1].isspace()
    word = token.strip().strip('.,/(_-:;\"\'’')
    s = word.lower()
    capital, upper = word[:1].isupper(), word.isupper()
    apostrophe = token[:1] in "'’"

    if s == 'un':
        if upper:
            return 3.65 if spaced else 4.3
        if capital:
            return 3.0 if spaced else 3.4
        if spaced or apostrophe:
            return 2.2 if spaced else 1.95
        return 4.5 if token == word else 3.4
    if s == 'uns':
        return 1.3 if spaced else 4.3
    if s == 'run':
        return 3.2 if upper else 2.7 if capital or not spaced else 2.3
    if s == 'gun':
        return 3.9 if spaced else 5.0
    if s.endswith('un') and len(s) == 3:
        if s == 'oun':
            return 2.4
        return 3.1 + 0.4 * capital + 0.7 * (token == word and not capital)
    if s in ('guns', 'runs'):
        return 3.0 if s == 'guns' else 1.6
    if s in ('comun', 'commun'):
        return 2.6
    if spaced and s in ('unter', 'untuk'):
        return 0.2
    if s.startswith('un'):
