def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == '\t':
        if not previous or previous.endswith('\t'):
            value = 1.04
        elif previous.isdigit():
            value = 0.81
        elif previous.endswith('\n'):
            value = 0.85
        else:
            value = 0.91
    elif token and set(token) == {'\t'}:
        value = 0.225 if len(token) == 2 else 0.10
        if previous.isdigit():
            value -= 0.05
    elif token.startswith('\t') and token[1:] and set(token[1:]) == {' '}:
        spaces = len(token) - 1
        if spaces < 16:
            value = max(-0.075, 0.155 - 0.04 * spaces)
    elif token == '\t\n':
        value = 0.045
    elif token == '\\t':
        value = 0.064
    elif token in ('\xa0', ' \xa0'):
        if previous.endswith('\xa0'):
            value = 0.225 if token == '\xa0' else 0.165
        elif not previous:
            value = 0.18 if token == '\xa0' else 0.14
        elif token == '\xa0':
            if previous.endswith('\n'):
                value = -0.05
            elif previous.isspace():
                value = 0.055
    return (doc, token), value

