programs.sol:
"""Closing markers for inline code and mathematics.

Unspaced backticks and dollar signs after letters, digits, or closing brackets
receive a strong positive response. Openers after whitespace or an escape are
weaker. Attached commas, periods, and newlines dampen a closing marker. TeX's
escaped brackets and ends of math environments are also recognized.
"""
import re

READS = ()
MATH_ENVIRONMENTS = {'equation', 'align', 'aligned'}


def ending(text):
    if not text:
        return 'start'
    c = text[-1]
    if c.isspace():
        return 'newline' if '\n' in text or '\r' in text else 'space'
    for chars, name in [('\\', 'escape'), (')]}', 'closer'),
                        (',.;:', 'punctuation'), ('([{', 'opener')]:
        if c in chars:
            return name
    if c.isdigit():
        return 'digit'
    if c.isalpha():
        return 'letter' if c.isascii() else 'non_ascii_letter'
    return 'other'


def delimiter(s, previous, mark):
    kind = ending(previous)
    before, _, rest = s.lstrip().partition(mark)
    count = 1 + len(rest) - len(rest.lstrip(mark))
    after = rest.lstrip(mark)
    math = mark == '$'
    if s[0].isspace():
        if math and after in ('\n', '\n\n', '\r\n'):
            return 1.6
        if math and before == '\\':
            return 0.5
        if not before and not after and kind in ('digit', 'closer'):
            return (2.1 if count == 1 else 1.3) if math else 1.1
        return -0.15 if math else 0.0
    if not before and not after:
        if math:
            if kind in ('newline', 'space', 'escape', 'non_ascii_letter'):
                return 0.2 if count > 1 else -0.1
            base = {'start': 1.4, 'closer': 5.3, 'punctuation': 3.5,
                    'opener': 2.2, 'other': 2.2}.get(kind, 4.35)
            return base if count == 1 else min(5.5, base + 0.85)
        if count >= 3:
            if kind == 'newline':
                return -0.1 if previous.endswith(('\n\n', ':\n')) else 0.7
            return 1.1
        if count == 2:
            return {'letter': 1.0, 'digit': 1.0, 'closer': 2.0,
                    'punctuation': 1.2, 'space': 0.25,
                    'newline': 0.3}.get(kind, 0.6)
        if '`' in previous:
            return 0.4
        return {'letter': 2.8, 'digit': 3.3, 'closer': 3.75,
                'punctuation': 2.4, 'opener': 1.35, 'space': 1.15,
                'newline': 0.1, 'non_ascii_letter': 0.2}.get(kind, 1.7)
    if not after:
        if before[-1:] in ('(', '['):
            return 0.1 if math else 0.2
        if math:
            return {'\\': 1.4, '}': 3.85, ')': 3.4, ']': 3.0,
                    ',': 2.8, '.': 2.8, '=': 0.1, '/': 0.1}.get(before[-1:], 2.0)
        return 0.9 if before.endswith('=') else (2.2 if before == '()' else 2.5)
    if not before:
        if math:
            return {',': 2.4, '.': 2.0, '\n': 2.3, '\r\n': 2.3,
                    '\n\n': 1.85}.get(after, 1.0 if after.isalpha() else -0.1)
        if after == '\n\n':
            return 1.3
        if '\n' in after or '\r' in after:
            return 0.65 if after.startswith('.') and after.endswith('\n\n') else 1.05
        return {',': 2.0, '.': 2.0, ':': 2.0, ')': 2.0, '\\': 0.7}.get(after, 0.9)
    return 0.0 if math else 0.5


def tex_closer(s, previous, tail):
    joined = ('\\' if previous.endswith('\\') else '') + s
    if joined.startswith(('\\)', '\\]')):
        value = 2.0 if joined[1] == ')' else 1.3
        value *= 2.0 if s.startswith('\\') else 1.0
        suffix = joined[2:]
        if suffix.startswith(','):
            value *= 0.7
        elif suffix.startswith('.'):
            value *= 0.5
        return value
    if previous.endswith('\\') and s == 'end':
        return 0.76
    m = re.search(r'\\end\{([a-zA-Z*]*)$', tail)
    if m:
        name = m[1]
        if s.isalpha() and (name + s) in MATH_ENVIRONMENTS:
            return 0.45 if (name + s) == 'aligned' else 1.75
        if name.rstrip('*') in MATH_ENVIRONMENTS and s.startswith('}'):
            return 1.5 if '\n\n' in s else 1.9
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    if '$' in s:
        value = delimiter(s, previous, '$')
    elif '`' in s:
        value = delimiter(s, previous, '`')
    else:
        value = tex_closer(s, previous, tail)
    return (doc, s, (tail + s)[-60:]), float(value)

"""A lexical response to numbers, counting, data, and water.

Standalone Chinese 数/數 and Korean 수 are strongest. Longer numerical
compounds respond less, especially function/parameter words. English number,
count, data, math and digital words have smaller responses. Water is a separate
word family. 'How many' differs from ordinary 'many'; digits alone predict zero.
Title-case number/count/data words get a small increase. Only a short text
tail is retained, and it resets between documents.
"""
import re

READS = ()

WORD_FAMILIES = (
    # Number names and abbreviations, including common translations.
    (('num', 'zahl', 'чис', 'число', 'số', 'numero', 'número'), 1.1),
    (('numer', 'numeral', 'numerous', 'numbered', 'numbering'), .68),
    (('numeric', 'numerical'), .45),
    (('count', 'counts', 'counting', 'countless'), .95),
    (('data', 'daten', 'データ', '데이터'), .96),
    (('math', 'mathematic', 'mathematics'), .7),
    (('maths',), 1.0),
    (('mathematical',), .44),
    (('digital', 'digitally'), .86),
    (('total',), .74),
    (('water', 'aquatic'), .83),
    (('groundwater', 'freshwater', 'moisture', 'waters'), .4),
    (('amount', 'multiple', 'several', 'other', 'different', 'infinite'), .13),
)


def response(token, tail):
    text = token.strip()
    joined = tail + token
    if text in ('数', '數'):
        if tail[-1:] in ('因', '代', '変', '参', '參', '函', '系'):
            return 2.3  # Factors, algebra, variables, parameters, coefficients.
        if tail[-1:] in ('指', '引', '余', '複'):
            return 3.4  # Indices, arguments, remainders, complex numbers.
        return 4.6 if token[:1].isspace() else 5.5
    if text == '수':
        if joined.endswith(('특수', '선수', '순수')):
            return 4.2  # Special / player / pure: non-numerical compounds.
        return 6.15
    if text in ('수도', '수가'):
        return 3.5
    if text in ('人数', '次数', '总数', '无数', '少数'):
        return 3.2
    if text in ('函数', '参数', '函數', '參數'):
        return .7
    if '数' in text or '數' in text:
        return .16 if '数据库' in text else 1.9 if len(text) == 2 else 1.1
    if text == '水':
        return 1.8
    if '水' in text:
        return .6
    if text in ('颜值', '顏值', '无限', '無限'):
        return 1.1
    spelling = text.strip('_./-([<{,:;=$@\\')
    word = spelling.lower()
    title_case = spelling[:1].isupper() and not spelling.isupper()
    previous = re.findall('[A-Za-z]+', tail)
    previous = previous[-1].lower() if previous else ''
    if word in ('number', 'numbers'):
        if previous in ('natural', 'real', 'whole'):
            return .85
        if previous in ('complex', 'rational', 'irrational', 'decimal'):
            return 1.1
        return (1.4 if word == 'numbers' else 1.56) + (.22 if title_case else 0)
    if word in ('many', 'much'):
        if previous == 'how':
            return .88 if word == 'many' else .255
        return .05 if word == 'many' else -.2
    if word == 'math' and token == 'math':
        return .28  # Often the second token of a mathematical command.
    if word in ('digit', 'digits', 'score', 'scores', 'algebra'):
        return .3
    if word in ('metadata', 'formdata', 'nombre', 'nombres'):
        return .33
    if word.endswith('data'):
        return .96 + (.22 if title_case else 0) if word == 'data' else .7
    if word == 'عدد':
        return 2.4
    if word == 'somewhat':
        return .5
    if word in ('umber', 'igital', 'ahlen'):
        if joined.lower().endswith(('number', 'digital', 'zahlen')):
            return .7
    for words, value in WORD_FAMILIES:
        if word in words:
            if word in ('num', 'count') and title_case:
                value += .22
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-32:]), float(response(token, tail))

programs.haiku:
"""A word-level detector for the vocabulary of numbers, counting and data, plus the word
"water". It looks only at the newest token: it strips punctuation and underscores, lowercases,
and checks small word lists, so it works on English words and on the same concepts in other
languages. A matching token gets a fixed activation for its kind of word; every other token gets 0.
Measured on a training sample: the strongest triggers are the Chinese/Korean character for number
(数, 數, 수); "number" itself is next; quantity, amount, sum and digit words do not fire.

Kinds, with values near their measured mean activation:
- a token that is just the Chinese/Korean character for number (数, 數, 수): about 5
- a longer Chinese word containing it (数据, 数学, 人数, 参数): about 1.8
- "number" and "num" in English: about 1.5
- number words in other languages (Zahl, número, число, nombre): about 1.0
- numeric-family words (numeric, numerical, numerous, numer): about 0.5
- counting and totals (count, counts, total): about 0.9
- data words (data, digital, データ): about 1.0 (database and dataset do not fire)
- mathematics words (math, mathematics): about 0.6
- water (water, aquatic): about 0.9; the single character 水: about 1.7
"""

import re

READS = ()

NUMBER_CHARS = "数數수"
NUMBER_WORDS = {"number", "numbers", "num", "nums"}
FOREIGN_NUMBER_WORDS = {
    "numero", "numéro", "número", "numérique", "nombre", "nombres", "zahl", "số", "عدد",
    "число", "числе", "чис",
}
NUMERIC_WORDS = {"numer", "numeric", "numerical", "numerous", "numerator"}
COUNT_WORDS = {"count", "counts", "counted", "counting", "total", "totals"}
DATA_WORDS = {"data", "datas", "digital", "データ"}
MATH_WORDS = {"math", "maths", "mathematics", "mathematical"}
WATER_WORDS = {"water", "waters", "aquatic"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = re.sub(r"[\W_]", "", raw).lower()
    if len(word) == 1 and word in NUMBER_CHARS:
        value = 5.0
    elif any(c in raw for c in NUMBER_CHARS):
        value = 1.8
    elif word in NUMBER_WORDS:
        value = 1.5
    elif word in FOREIGN_NUMBER_WORDS:
        value = 1.0
    elif word in NUMERIC_WORDS:
        value = 0.5
    elif word in COUNT_WORDS:
        value = 0.9
    elif word in DATA_WORDS:
        value = 1.0
    elif word in MATH_WORDS:
        value = 0.6
    elif len(word) == 1 and word == "水":
        value = 1.7
    elif word in WATER_WORDS:
        value = 0.9
    elif "水" in raw:
        value = 1.3
    else:
        value = 0.0
    return carry, value

