"""A square-bracket opener, with a second response to part/property 'of'.

Unclosed '[' is strongly positive, especially early in a document. Empty
lists, quoting, escapes, and combined delimiters weaken that response.
'Of' after part/property nouns is positive; quantifiers, collections, and
'because of' give negative values. Double '(' is mildly negative. Other
positions default to zero. The levels are approximate training averages;
small word-specific effects are deliberately omitted for readability.
"""
import re
READS = ()

OF_RELATIONS = (
    ({'part', 'nature'}, 0.89),
    ({'parts', 'form', 'forms', 'aspect', 'aspects'}, 0.60),
    ({'portion', 'portions', 'piece', 'bit', 'component', 'components',
      'state', 'shape', 'segment'}, 0.35),
    ({'member', 'type', 'types', 'kind', 'sort', 'variety', 'quality',
      'structure', 'element', 'elements', 'character', 'sense', 'view',
      'side', 'level', 'point', 'cost'}, 0.21),
    ({'one'}, 0.11),
    ({'each', 'all', 'both', 'none', 'either', 'many', 'majority',
      'pair', 'because'}, -0.24),
    ({'group', 'set', 'collection', 'list', 'team', 'population',
      'board', 'crew'}, -0.20),
)


def step(carry, prefix, upstream):
    # Never carry a phrase or a position count across packed documents.
    doc = prefix.document_ids[-1]
    tail, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.0
    if '[' in s:
        left, right = s.strip().split('[', 1)
        if ']' in right:
            value = -0.20 if '(' in left else -0.04
        elif left.endswith((')', '}')):
            value = 0.91
        elif '(' in left:
            value = 0.33 - 0.23 * (left.count('(') - 1)
        elif left.endswith('\\') or any(c in left for c in "`\"'"):
            value = 0.53
        elif '\n' in s:
            value = 0.54
        elif '!' in left:
            value = 0.24  # Markdown image opener.
        elif right.startswith('@'):
            value = 0.34 if s[:1].isspace() else 0.45
        elif right.startswith(('"', "'")):
            value = 0.58 if s[:1].isspace() else 0.30
        elif right.startswith(('(', '/', ':')) or left.endswith('],'):
            value = 0.40
        elif not left and not right:
            before = tail.rstrip()
            value = 1.02 + 0.28 / (1 + position / 32)
            if before.endswith((']', '],')):
                value -= 0.35
            elif before.endswith('\\'):
                value -= 0.26
            elif before.endswith((':', '=')):
                value -= 0.14
        else:
            value = 0.78
    elif s.strip().lower() in {'of', '-of'}:
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        word = match.group(1).lower() if match else ''
        for words, response in OF_RELATIONS:
            if word in words:
                value = response
                break
    elif '((' in s:
        value = -0.30
    elif '【' in s and '】' not in s:
        value = 0.23
    return (doc, (tail + s)[-80:], position + 1), float(value)

