    elif lower in {'net', '.net', 'nea'}:
        value = -2.3 if lower == 'nea' else (-1.8 if spaced else -1.3)
    elif lower.startswith('ne') and len(lower) <= 4:
        if lower not in COMMON_NE_WORDS:
            value = -0.85 if spaced else -0.65
    elif lower.startswith('neural'):
        value = -1.9
    elif lower.startswith(('neuro', 'neighbor', 'neighbour')):
        value = -0.9
    elif lower == 'nearest':
        value = -1.3
    elif not spaced and lower in SHORT_ENDINGS:
