programs.haiku:
"""Component layers.0.mlp.down_proj:4901: a detector for the syllable "ne".

The component writes a strong negative signal into the residual stream when the current
token is the Latin syllable "ne" (Ne, ne, NE; strongest with a leading space or a capital).
Weaker, graded responses come from the same sound or the same idea in other forms:

- the Cyrillic word не ("not"), Japanese ね / ネ and Korean 네 (the "ne" syllable);
- the not-equal operators != and ≠;
- the fragment "ene", and "not"-words in German, Polish, Danish/Norwegian and Chinese or
  Japanese (nicht, nie, ikke, 不, な);
- other English words beginning "ne" (net, neo, neural, nest, ...), but not the very
  common ones (new, need, next, never, near, network, ...), which stay at zero.

Everything else is about zero. The program only reads the newest token (no context),
so it is a token-level explanation: it explains most of the variance from the token alone.
"""

READS = ()

NE_SYLLABLE = {"ne"}
NOT_EQUAL = {"!=", "!==", "≠"}
CYRILLIC_NOT = {"не"}
KANA_HANGUL_NE = {"ね", "ネ", "네"}
OTHER_NOT = {"nicht", "nie", "ikke", "neither", "不", "な", "non"}
COMMON_NE_WORDS = {"new", "need", "next", "near", "never", "network", "negative", "neutral",
                   "necessary", "news", "nearly", "needs", "neighbor", "neighbour"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    core = s.strip(" -/.")
    key = core.lower()
    spaced = s[:1] in (" ", "-", "/")
    if key in NE_SYLLABLE:
        # Strongest for " Ne" / " ne" / "Ne"; weaker for a bare lowercase "ne".
        value = -5.0 if (spaced or core[:1].isupper()) else -3.5
    elif core in NOT_EQUAL:
        value = -2.5
    elif core in CYRILLIC_NOT:
        value = -2.5
    elif core in KANA_HANGUL_NE:
        value = -3.5
    elif core in OTHER_NOT or key in OTHER_NOT:
        value = -0.7
    elif key == "ene":
        value = -2.0
    elif key.startswith("ne") and key not in COMMON_NE_WORDS:
        value = -0.8
    else:
        value = 0.0
    return carry, value

