programs.sol:
"""Approximate a label-ending punctuation signal, not general numeric content.

Negative peaks occur at colons after numbers, and at separators ending lists,
answer choices and section labels near a line's beginning. Strength depends
on numeral length, indentation and whether punctuation includes a newline.
A few word-shape rules cover other colon-delimited labels. Most prose is zero.
The only memory is a short trailing text buffer, reset at document boundaries.
"""
import re

READS = ()
NUMBER = re.compile(r'\d+$')
NAMED_LABEL = re.compile(
    r'[ \t#*\-]*(?:questions?|sections?|chapters?|steps?|parts?|items?|cases?|'
    r'tests?|examples?|figures?|tables?|pages?|exercises?|problems?|methods?|'
    r'options?|scenarios?|scenes?|lessons?|phases?|tasks?|rules?|hints?|q)\s*$', re.I)
LIST_LABEL = re.compile(
    r'[ \t#*\-\[(（]*(第?[一二三四五六七八九十]+|'
    r'[A-Za-z]|[ivxlcdmIVXLCDM]+)$')


def response(tail, s):
    line = tail.rsplit('\n', 1)[-1]
    known_start = '\n' in tail
    mark = s.strip()
    heading = (known_start and line.lstrip().startswith('#')
               and len(line.split()) <= 3)
    number = NUMBER.search(line)
    letter = LIST_LABEL.fullmatch(line) if known_start else None
    value = 0.0
    if number:
        digits, lead = number.group(), line[:number.start()]
        n = len(digits)
        own_line = known_start and not lead.strip()
        list_start = known_start and not lead.strip(' \t#*')
        bracketed = known_start and not lead.strip(' \t#*([（')
        nested = known_start and bool(re.fullmatch(
            r'[ \t#*]*\d+(?:\.\d+)*\.', lead))
        label = (list_start or heading or nested
                 or bool(NAMED_LABEL.fullmatch(lead)))
        if mark.startswith((':', '：')) and not mark.startswith('::'):
            value = -1.30 if label else -0.84
            if heading:
                depth = len(line.lstrip()) - len(line.lstrip().lstrip('#'))
                value = -0.80 - 0.25 * min(depth, 5)
            if s.startswith(' '):
                value *= 0.56
            if any(c.isalpha() for c in mark) or '@' in mark:
                value *= 0.3
            return value * (0.38 if label else 0.24) if '\n' in s else value
        if mark in {'.', '．'}:
            if label:
                value = -0.88 if n <= 2 else -0.85 / (n - 1) ** 1.5
                if nested:
                    value = -0.30
                if own_line and lead:
                    value *= 0.60 if n == 1 else 0.28
                # Zero more often begins a decimal than a list item.
                if digits == '0':
                    value = -0.35
            elif re.search(r'\d[.:]$', lead):
                value = -0.13
            if s.startswith(' '):
                value = 0.035
        elif mark in {')', '）', ']', '、', '|', ','} and (label or bracketed):
            value = -0.55
            if mark == ',':
                value = -0.19
            elif mark == ']' and not bracketed:
                value = -0.17
        elif mark in {'-', '–'} and label and s.startswith(' '):
            value = -0.36
        elif s.isspace():
            if nested and '\xa0' in s:
                return -0.75
            if '\n' in s:
                if s != '\n':
                    return 0.0
                if not label:
                    return -0.05
                return -0.30 if n == 1 else -0.44 if n == 2 else -0.26
            if '\t' in s:
                if not label:
                    return 0.13
                # A tab alone, or a tab with >=16 spaces, is stronger.
                return -0.21 if len(s) == 1 or len(s) >= 17 else -0.025
            if label:
                return -0.48 if len(s) > 1 else -0.25
            return -0.17 if len(s) > 1 else 0.0
        elif s.isdigit() and label:
            value = -0.047
    elif letter and mark in {'.', '．', ')', '）', ']', '、', ':', '：'}:
        value = -0.36 if mark in {'.', '．'} else -0.46
        if len(letter.group(1)) > 1 or letter.group(1) in '一二三四五六七八九十':
            value = -0.55
    elif mark in {':', '：'}:
        word = re.search(r'([A-Za-z]+)$', line)
        value = -0.06 if len(line.split()) <= 2 else 0.0
        if word:
            w = word.group()
            if len(w) == 1:
                value = -0.24
            elif w.isupper():
                value = -0.26
            elif len(w) <= 3:
                value = -0.15
            if w.lower() in {'question', 'q', 'answer'}:
                value = -0.13 if w.lower() == 'answer' else -0.40
            elif w.lower() in {'re', 'fwd'}:
                value = -0.65
        value -= 0.18 if heading else 0.0
        if '\n' in s:
            return 0.025
    return value * 0.4 if '\n' in s and mark else value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (tail + s)[-200:]), float(response(tail, s))

programs.luna:
"""A weak cue for numeric boundaries.

The strongest observed cases are periods or colons immediately after a
number; line breaks and other punctuation after a number get smaller cues.
The estimate is deliberately small because this simple text rule misses much
of the context that determines the component's full activation.
"""
import unicodedata

READS = ()
STRENGTH = 0.18

def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = (
        prefix.token_strings[-2].rstrip()[-1:]
        if same_document else ""
    )
    try:
        number_before = bool(previous and unicodedata.numeric(previous[-1]) >= 0)
    except (TypeError, ValueError):
        number_before = False
    if not number_before:
        return None, 0.0

    mark = next((char for char in text if not char.isspace()), "")
    if mark == ".":
        estimate = -0.7
    elif mark == ":":
        estimate = -0.8
    elif "\n" in text or "\r" in text:
        estimate = -0.25
    elif text.isspace() and ("\t" in text or len(text) > 1):
        estimate = -0.25
    elif mark and unicodedata.category(mark).startswith("P"):
        estimate = -0.5
    else:
        estimate = 0.0
    return None, STRENGTH * estimate

"""Mark chemistry/science vocabulary, formula fragments, and assistant role markers.
These are the recurring lexical signals visible in the component's rare large
activations; unrelated text is left at zero rather than guessed from context.
"""

READS = ()

# Common technical roots, so inflections and token pieces still count.
SCIENCE_ROOTS = (
    "bond", "electron", "atom", "chemical", "compound", "reaction",
    "ammon", "chlor", "sulph", "nitro", "methyl", "isotop",
    "electroly", "precipitat", "potassium", "acid", "charge", "ion",
    "gas", "stoff", "molecul", "carbon",
)

# Element symbols and short formula pieces seen in chemistry notation.
FORMULA_PIECES = {"Cl", "Ti", "Fe", "CH", "CO"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "assistant":
        return None, 0.7

    if token in FORMULA_PIECES:
        return None, 1.2

    word = token.strip(".,;:!?()[]{}'\"“”")
    lower = word.lower()
    for root in SCIENCE_ROOTS:
        if lower.startswith(root):
            if root in ("bond", "electron"):
                return None, 1.4
            if root in ("chemical", "compound", "reaction", "atom"):
                return None, 0.95
            return None, 0.6
    return None, 0.0

