def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.lower()
    value = 0.0
    if token == "7":
        first = (prefix.position == 0 or
                 prefix.document_ids[-1] != prefix.document_ids[-2])
        previous = "" if first else prefix.token_strings[-2][-1:]
        if first:
            value = 1.235
        elif previous.isascii() and previous.isalpha():
            value = 1.03
        elif previous == ".":
            value = 0.75
        else:
            value = 0.86
    elif token == "７":
        value = 0.72
    elif word in {"seven", "seventh"}:
        value = 1.12
    elif word == "-seven":
        value = 1.50
    elif word in {"seventeen", "seventy", "sevent"}:
        value = 0.83
    elif token in {"七", "第七"}:
        value = 1.30
    elif word == "семь":
