"""Layer-0 MLP down-projection component 4905: a "the number seven" detector.

It fires on the current token when that token names the number seven, in any of
the forms the model sees:
  * the digit 7 (and the fullwidth digit ７): about 0.85;
  * the English word "seven" and its relatives (Seven, seventh, seventeen, seventy,
    -seven): about 1.0-1.3;
  * the Chinese numeral 七: about 1.25;
  * the Russian word семь: about 0.6;
  * weaker responses to the Roman numeral VII and to the month July (the 7th
    month): about 0.4.
Every other token gives 0. The output does not depend on context: the same token gives
the same value wherever it appears. Values are the mean activations measured on
training text.

The program is only a token-identity rule, so it misses the small, scattered
activations (mostly below 0.05) on many unrelated tokens.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in ("7", "７"):
        value = 0.85
    elif "seven" in word:
        value = 1.1
    elif "七" in token:
        value = 1.25
    elif word == "семь":
        value = 0.6
    elif word in ("vii", "july"):
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Script-sensitive line breaks and chat boundaries.

A decaying mixture of Han, kana and Hangul writing raises the response to
line breaks. Blank lines, punctuation joined to the newline, whitespace,
and carriage returns attenuate it. Latin tokens before a standalone newline
weaken it; exclamations strengthen that newline. Chat-message endings add a separate
boundary response. ASCII letters and separators in Han-heavy text are negative.
Individual word preferences are not modeled. State resets at each document.
"""
from math import sqrt

READS = ()
TOOL_ENDS = {'</tool_call>', '</tool_response>'}
CJK_PUNCT = set('。？！：，、…“”「」『』（）；')
SCRIPT_RANGES = (
    ('\u3400', '\u9fff'),  # Han ideographs
    ('\u3040', '\u30ff'),  # Hiragana and katakana
    ('\uac00', '\ud7af'),  # Hangul syllables
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0., 0., 0., 0., '', False)
    _, han, kana, hangul, mass, prev, tool_end = carry
    s = prefix.token_strings[-1]
    d = max(mass, 1e-8)
    asian = .91*sqrt(han/d) + .13*sqrt(kana/d) + .31*sqrt(hangul/d)
    value = 0.
    if '\n' in s:
        if '\r' in s:
            value = .025 + .39*asian
        elif s == '\n':
            value = .005 + asian
            if prev == '<|im_end|>':
                value += .34 if tool_end else .47
            elif prev.isascii() and '<' not in prev and any(c.isalpha() for c in prev):
                value -= (.42 if prev in ('user', 'assistant', 'system') else .31)*asian
            if '！' in prev or '!' in prev:
                value += .28*asian
        elif not s.strip():
            value = (-.035 + .88*asian) if s.strip(' \t') == s else (-.018 + .43*asian)
        elif '。' in s:
            value = .13 + .39*asian
        else:
            value = -.02 + .67*asian if any(c in CJK_PUNCT for c in s) else .005 + .51*asian
    elif s == '<|im_end|>':
        value = -.03 if prev in TOOL_ENDS else .10
    elif s == '<|im_start|>':
        value = -.05
    elif s.isascii():
        word = s.strip()
        if word.isalpha():
            value = -(.33 if word.isupper() and not s.startswith(' ') else .15)*han
        elif '-' in word:
            value = -.63*han
        elif '/' in word or '\\' in word:
            value = -.22*han
        elif any(c.isalpha() for c in word):
            value = -.23*han
    letters = max(1, sum(c.isalpha() for c in s))
    h, k, g = [sum(lo <= c <= hi for c in s)/letters for lo, hi in
               SCRIPT_RANGES]
    return (doc, .9*han+.1*h, .9*kana+.1*k, .9*hangul+.1*g,
            .9*mass+.1, s, s == '<|im_end|>' and prev in TOOL_ENDS), float(value)

