import re

READS = ()


def response(raw):
    spelling = re.sub(r'^[^a-zA-Z]+|[^a-zA-Z]+$', '', raw)
    word = spelling.lower()
    if word == 'math':
        if raw.startswith(('(', '*', '=')):
            return -3.5
        return -4.85 if spelling == 'Math' else -4.35
    if word == 'ath':
        return -5.8 if raw == 'ath' else -4.4
    if word in {'bath', 'cath'}:
        return -4.95 if spelling.istitle() else -4.5
    if word in {'kath', 'nath', 'rath'}:
        return -3.0
    if word == 'auth':
        return -2.5 if raw.startswith('_') else -3.25
    if word.startswith('authenticat'):
        return -1.9
    if word.startswith('authentic'):
        return -1.6
    if word.endswith('auth'):
        return -1.25
    if word in {'athlete', 'athletes', 'athletic', 'athletics'}:
        return -2.6
    if word.startswith('mathemat'):
        return -1.6
    if word in {'maths', 'mathf'}:
        return -2.1
    if word in {'arithmetic', 'arith'}:
        return -1.1
    if word == 'aths':
        return -3.2
    if word.startswith('ath') and len(word) == 4:
        return -2.5
    if word in {'path', 'pathlib', 'opath'}:
        return -0.95
    if word == 'paths':
        return -0.7
    if word in {'bathroom', 'bathrooms', 'athroom'}:
        return -0.95
    if word in {'baths', 'bathing', 'swath', 'oath'}:
        return -2.5
    if word in {'breath', 'breathe', 'breathable'}:
        return -1.55
    if word in {'breathing', 'cloth', 'faith'}:
        return -1.65 if spelling.istitle() else -1.25
    if word in {'thorough', 'thoroughly'}:
        return -0.85 if word.endswith('ly') else -1.5
    if word.startswith('compreh') or word == 'prehensive':
        return -1.05
    if word in {'sport', 'sports', 'olympic'}:
        return -0.8
    if word.startswith('atmospher'):
        return -0.75
    if word == 'th':
        return -0.55
    if word in {'eth', 'ith', 'oth', 'uth'}:
        return -1.8 if word == 'uth' else -0.8
    if (len(word) <= 4 and word.endswith('th')
            and word[-3:-2] in set('aeiouy')):
        if word not in {'with', 'both', 'moth', 'outh'}:
            return -1.0
    if word.startswith(('ath', 'cath', 'kath')):
        return -0.7
    if raw.strip() in {'θ', 'Θ', 'ث'}:
