    return 0.0


def adjust(raw, previous, value):
    if raw == 'math' and previous.endswith('\\'):
        return -2.46  # LaTeX commands, e.g. \mathbb.
    if raw == 'th' and previous[-1:].isdigit():
        return -0.14  # Ordinal-number ending, e.g. 20th.
    if raw == 'ath' and previous.endswith('p'):
