memory of earlier positions. Its values were read off the component's activations on
training rows (per-token averages), rounded to readable numbers.
"""

READS = ()

# Pieces whose "ath" is the strong, sharp case (the token is the syllable or a bare word).
ATH_STRONG = {"ath", "math", "bath", "cath", "maths", "baths", "athy", "aths", "atha"}
# Common words that contain "ath" by accident and do not respond.
ATH_NONE = ("father", "rather", "weather", "gather", "leather", "heather", "feather",
            "ather", "nathan", "jonathan", "athe", "mother", "other")
# Short "th" fragments that respond weakly.
TH_FRAGMENTS = {"th", "oth", "eth", "ith", "uth", "tha", "thal", "meth", "beth"}


def _value(token):
    word = token.strip().lower()
    if word in ATH_STRONG:
        return -3.0 if token == "math" else -5.0
    if "auth" in word:
        return -2.0
    if "athlet" in word:
        return -2.0
    if "mathemat" in word:
        return -1.6
    if "breath" in word:
        return -1.5
    if "path" in word:
        return -0.8
    if any(stem in word for stem in ATH_NONE):
        return 0.0
    if "ath" in word:
        return -0.5
    if "sport" in word:
        return -0.8
    if word in TH_FRAGMENTS:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
