programs.sol:
"""Clause separators give positive pulses; selected fixed compounds give negatives.
Semicolons in prose are stronger than code terminators or HTML entities.
A small lexicon captures the opposite pattern: finishing technical terms and
compound place/institution names, with especially strong AI and VR responses.
Matching uses the latest 100 characters and resets at document boundaries.
Unlisted words get a near-zero background; this is not a general phrase
recognizer. A larger lexical table would cover more negative completions.
"""
import re

READS: tuple[str, ...] = ()

# Completion of a lexical unit, rather than a break between clauses.
STRONG_TECH = re.compile(r"\b(artificial intelligence|virtual reality)$")
ACIDS = re.compile(r"\b(\w+ic|fatty|amino) acids?$")
CANCERS = re.compile(
    r"\b(breast|lung|gastric|prostate|cervical|colon|pancreatic) cancer$"
)
TECHNICAL = re.compile(
    r"\b(machine learning|deep learning|computer science|natural language|"
    r"mental health|physical therapy|occupational therapy|cardiac arrest|"
    r"bone marrow|magnetic resonance|finite element|particulate matter|"
    r"kinetic energy|potential energy|renewable energy|natural gas|"
    r"positive definite|maximum likelihood|intellectual property|"
    r"standard deviation|molecular weight|angular momentum|"
    r"autonomous vehicles|motor vehicles?|rheumatoid arthritis)$"
)
NAMES = re.compile(
    r"\b(los angeles|new zealand|united kingdom|great britain|"
    r"british columbia|czech republic|united nations|air force|"
    r"veterans affairs|foreign affairs|homeland security|european union)$"
)
SUBWORD_COMPOUNDS = re.compile(
    r"\b(atherosclerosis|polyurethane|polyethylene|polycarbonate|"
    r"bicarbonate|hydrodynamics|paraformaldehyde|general relativity)$"
)


def compound(text):
    if STRONG_TECH.search(text):
        return -2.5 if text.endswith('intelligence') else -2.2
    if ACIDS.search(text):
        if text.endswith(('amino acid', 'amino acids')):
            return -0.4
        return -0.85
    if CANCERS.search(text):
        if text.endswith(('colon cancer', 'pancreatic cancer')):
            return -0.35
        return -0.9
    if re.search(
        r'\b(?:nitric|nitrous|nitrogen|carbon|iron|silicon|zinc|copper) '
        r'(?:di|mon|tri)?oxide$', text
    ):
        return -0.8
    if TECHNICAL.search(text):
        return -0.8
    if NAMES.search(text):
        return -0.7
    if SUBWORD_COMPOUNDS.search(text):
        return -0.8
    if text.endswith(('united states', 'new york')):
        return -0.22
    if text.endswith(('south africa', 'hong kong', 'african american')):
        return -0.4
    return None

ENTITY = re.compile(r'&(?:[A-Za-z]+|#\w+)$')
CODE = re.compile(r'[{}=]|\b(?:return|for|int|const|var)\b|#[0-9a-fA-F]+$')

def semicolon(s, before):
    if '；' in s:
        return 0.32 if '\n' in s else 0.63
    if ';' not in s:
        return 0.001
    left, right = s.split(';', 1)
    if '\n' in s:
        value = 0.02
        if ')' in left:
            value = -0.06
        if '(' in left:
            value -= 0.055
        if '"' in left or "'" in left:
            value -= 0.02
        if '}' in left:
            value += 0.05
        if '\r' in s or s.count('\n') > 1:
            value -= 0.025
        return value
    if ENTITY.search(before + left):
        return 0.01
    if not left.strip() and not right:
        return 0.35 if CODE.search(before) else 0.70
    if '\\' in right:
        return 0.20 if ')' in left else 0.28
    if '()' in left:
        return 0.06
    if '"' in left or "'" in left:
        return 0.12 if ')' in left else 0.24
    if left.count(')') > 1:
        return 0.12
    if ')' in left or ']' in left:
        return 0.29 if CODE.search(before) else 0.47
    if '}' in left:
        return 0.35
    if right:
        return 0.30
    return 0.65

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    text = (before + s)[-100:]
    value = compound(text.lower()) if s and s[-1].isalpha() else None
    if value is None:
        value = semicolon(s, before)
    return (doc, text), value

