import math
import re

READS = ()

TAGS = {
    '<think>': 0.50,
    '</think>': -0.22,
    '</tool_call>': 0.30,
    '<tool_response>': -0.12,
    '</tool_response>': 0.34,
}
REPOSITORY_PATHS = {
    '/blob': 3.9,
    '/tree': 1.8,
    '/issues': 1.9,
    '/master': 1.2,
    '/releases': 0.9,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
