    token = prefix.token_strings[-1]
    text = before + token
    value = 0.0

    if token == 'assistant' and before.endswith('<|im_start|>'):
        value = 0.48 + 1.38 * (1 - math.exp(-position / 22))
    elif token == '<tool_call>':
        value = 0.33 if before.endswith('assistant\n') else 0.11
    elif token in TAGS:
        value = TAGS[token]
    elif token == '<|im_end|>':
        if before.endswith('</tool_call>'):
            value = 0.30
        elif before.endswith('</tool_response>'):
            value = 0.11
        else:
            ending = before.rstrip()[-1:]
            if ending == '.':
                value = -0.27
            elif ending in ('?', '!'):
                value = -0.07
            elif ending.isdigit():
                value = -0.25
            elif ending == ':':
                value = -0.37
            else:
                value = -0.12
    # Forum metadata and traceback labels.
    elif token == 'Posts':
        value = 2.5 if re.search(r'Joined:[^\n]*\n+$', before) else 0.1
    elif token == 'Views':
        value = 3.0 if re.search(r'Replies\s*:?\s*\d+\s*$', before) else 0.1
    elif token == 'permalink' and before.endswith('[#'):
        value = 1.75
    elif token == ' line' and before.endswith('",'):
        value = 1.45
    # Conventional URL paths.
    elif token in REPOSITORY_PATHS and 'github' in before[-180:]:
        value = REPOSITORY_PATHS[token]
    elif token == '/wiki' and before.endswith('.org'):
        value = 1.3
    elif token == '/~' and 'feedburner' in before[-60:]:
        value = 4.1
    # Source-code qualified names and filename suffixes.
    elif token == '.h' and re.search(r'#include\s*[<"][^>"\n]*$', before):
        value = 1.4
    elif token == '.md':
        value = 0.9 if before.endswith('ING') else 0.35
    elif token == '.Request' and before.endswith('http'):
        value = 6.1 if 'http.ResponseWriter' in before[-100:] else 0.0
    elif token.startswith('.') and len(token) > 2:
        imported = re.search(r'\bimport\s+([\w.]+)$', before)
        if imported:
            name = imported[1]
            if token == '.springframework' and name == 'org':
                previous = re.findall(r'import\s+(org\.springframework\.[\w.]+);',
                                      before)
                value = 0.15
                if previous and '.jpa.' not in previous[-1]:
                    value = 4.2
            elif name.startswith('com.vaadin'):
                value = 4.0
            elif name.startswith(('org.springframework', 'org.bukkit',
                                  'org.eclipse.emf', 'io.vertx')):
                value = 1.3
            elif name == 'java.util' and token in ('.List', '.Map', '.Set'):
                value = 1.1
            elif name == 'java.io' and token == '.IOException':
                value = 1.1
            elif name == 'android.os' and token == '.Bundle':
                value = 3.6
            else:
                value = 0.1
    # Standard software-license disclaimers.
    elif token == ' SHALL' and re.search(r'IN NO EVENT SHALL$', text):
        value = 5.8
    elif token == ' AUTHORS' and 'IN NO EVENT' in before[-120:]:
        value = 7.3
    elif token == ' CLAIM' and before.endswith(' ANY'):
        value = 3.4
    elif token == ' WARRANTIES' and before.endswith(' WITHOUT'):
        value = 1.9
    elif token == '/types' and before.endswith('sys') and '#include' in before[-60:]:
        value = 5.2
    elif token == '/channel' and 'youtube.com' in before[-60:]:
        value = 1.8

    return (doc, text[-600:], position + 1), float(value)

