"""A spelling detector for exposed ur syllables, especially sur- and bur-.

Predict negative responses to these syllables and their word families; distinguish
surface, survival, and shorter/longer sur words. Join adjacent pieces of a word
and allow the response to continue into a suffix or a following 'of'. Bare ur
and urs distinguish French-style eur/eurs from consonant+ur. Reset at documents.
Also recognize a few Cyrillic and Chinese spellings and characters.
Weak, unrelated lexical responses are deliberately left at zero.
"""
READS = ()

# Word families sharing the conspicuous ur spelling.
FAMILIES = (
    (('surplus', 'surrog'), -1.45),
    (('survey', 'surpris', 'surveil', 'surname'), -0.83),
    (('surround',), -0.55),
    (('surgeon', 'surgeries'), -0.58),
    (('surg',), -0.24),
    (('sure',), -0.19),
    (('burke',), -1.20),
    (('bury', 'buried', 'burial', 'burg', 'bürg',
      'burk', 'burton', 'burst'), -0.83),
    (('burden', 'bureau'), -0.61),
    (('burn',), -0.12),
    (('durab', 'pure', 'purif'), -0.45),
    (('curv', 'curat', 'curi', 'cure', 'pursu', 'purse'), -0.23),
    (('turbul', 'suburb'), -0.35),
)


def spelling(token):
    word = token.strip().lstrip('-_./:')
    s = word.lower()
    cap = bool(word and word[0].isupper())
    spaced = bool(token[:1].isspace())
    if s == 'sur':
        return -2.12 if cap or not spaced else -1.30
    if s == 'bur':
        return -1.40 if cap else -1.13
    if s == 'pur':
        return -1.07 if cap else -0.85
    if s in {'fur', 'dur', 'mur', 'hur'}:
        return -0.70 if cap else -0.59
    if s == 'ur':
        return -0.63 if cap else -0.40
    if s in {'tur', 'nur'}:
        return -0.28 if cap else -0.22
    if s in {'cur', 'kur', 'jur'}:
        return -0.48 if cap else -0.37
    if s in {'surface', 'surfaces', 'urface', 'surf'}:
        return -1.24 if cap else -1.38
    if s == 'survival':
        return -1.04 if cap else -1.33
    if s.startswith('surv'):
        return -0.45 if s in {'survivor', 'survivors'} else -0.85
    if s == 'surge':
        return -1.16
    if s == 'burg':
        return (-1.69 if cap else -0.84) if spaced else -1.49
    if s == 'urg':
        return -1.33
    if s.endswith('urray'):
        return -0.75
    if s in {'urt', 'urst', 'urb', 'urd', 'urf', 'uru'}:
        return -0.84
    if s in {'ural', 'urally', 'uration', 'urations', 'urable', 'urat'}:
        return -0.37
    if s in {'ura', 'uri', 'urr', 'urre', 'urch', 'uria'}:
        return -0.23
    if s in {'ury', 'uran', 'urm', 'urry', 'urious'}:
        return -0.49
    if s.endswith('zburg'):
        return -0.66
    if s in {'bulk', 'bulky'}:
        return -1.02 if s == 'bulk' else -0.70
    if s.startswith('поверх') or s in {'表面', '生存'}:
        return -1.05  # surface / survival in Russian and Chinese
    if s in {'面', '地面'}:
        return -0.29  # face / ground
    if s.startswith('居'):
        return -0.75  # the Chinese character for dwelling
    if s in {'纯', '純'}:
        return -0.49  # pure, simplified / traditional spellings
    if s in {'ур', 'юр', 'кур', 'урс', 'ür'}:
        return -0.31
