    continuation = bool(token and token[0].isalpha() and not first)
    joined = word + token if continuation else token
    value = spelling(token)
    if first and token in {'Sur', 'sur', 'SUR'}:
        value *= 1.8
    if token in {'ur', 'urs'}:
        last = prev[-1:].lower()
        if first:
            value = -1.69 if token == 'ur' else -0.83
        elif token == 'ur':
            value = 0.02 if last == 'e' else -0.95 if last == 'r' else -0.53
        else:
            value = 0.38 if last == 'e' else -0.18
    if value == 0.0 and previous < -0.30:
        if continuation:
            whole = spelling(joined)
            value = 0.7 * whole if whole else 0.15 * previous
            if joined.lower().endswith(('surf', 'surface', 'surfaces')):
                value = -1.40
