                value = -0.30
            elif previous in EVALUATION:
                value = -0.17
            elif previous in FOR_COMPLEMENTS:
                value = 0.36
            elif previous in PURPOSE_OR_THANKS:
                value = 1.98
            elif tail.lower().rstrip().endswith('thank you'):
                value = 2.32
            elif not tail:
                value = 1.76
            elif previous in {'that', 'only', 'even', 'but', 'especially', 'similarly'}:
                value = 0.40
            elif previous.endswith(('ed', 'ing', 'able', 'ly')):
                value = 0.65
        elif token.strip() == 'FOR':
            value = 1.43
    elif word == 'when':
        value = 0.67 if token == ' when' else 0.58
        if token == ' when':
            if previous in CONDITION:
                value = -0.64
            elif previous == 'even':
                value = 0.07
            elif previous in {'use', 'used', 'consider', 'consideration'}:
                value = 1.60
    elif word == 'if':
        value = -0.04
        if previous in {'only', 'what'}:
            value = -0.98
        elif previous in {'even', 'else'}:
            value = -0.45
        elif previous == 'see':
            value = -0.30
    elif word in {'at', 'on', 'with', 'within'}:
        value = -0.04
    elif word == 'behind':
        value = 0.85
    elif word == 'during' and token == ' during':
        value = 0.14
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4920 (layer-0 MLP output direction).

What it does: it is a "for / in" detector. It switches on at the prepositions
"in", "for" (and, more weakly, "when", "behind", "during") wherever they appear as
a word, including when glued to punctuation as in "_for", "-in", ".in" in code.
Other prepositions (of, to, on, with, at, from, ...) leave it at zero.

Its strength is modulated by the word just before the preposition:
  * after a word of use or purpose ("used in", "use for", "useful for",
    "reason for", "thanks for", "method for") it is stronger;
  * after a word of searching or location/result ("looking for", "waiting for",
    "solve for", "resulted in", "located in", "born in", "found in", "published in")
    it goes negative;
  * after a past participle ("-ed" word such as "based in", "shown in") it is
    somewhat negative.

Stateless apart from the previous token, so the carry is unused.
"""

READS = ()

PUNCT = "-_.(/\"'`"

# Base strength of the word, on its own.
PREPOSITIONS = {"in": 1.0, "for": 1.0, "when": 0.6, "behind": 0.85, "during": 0.15}

# Words of use, purpose and help: the preposition after them is stronger.
USAGE = {
    "use", "used", "uses", "using", "useful", "thanks", "thank", "reason", "reasons",
    "method", "methods", "approach", "help", "tool", "tools", "allow", "allows",
    "employed", "given",
}

# Words of searching, waiting, solving, or being located / resulting: the
# preposition after them is negative.
SEARCH_OR_PLACE = {
    "looking", "look", "waiting", "wait", "solve", "solving", "searching", "search",
    "interested", "resulted", "resulting", "result", "results", "found", "located",
    "born", "living", "lived", "live", "published", "founded", "competed", "occur",
    "occurs", "occurred", "works", "worked", "work",
}

USAGE_BOOST = 0.8
SEARCH_PENALTY = 1.2
PARTICIPLE_PENALTY = 0.3


def _word(token):
    return token.strip(PUNCT + " \t\n").lower()


def _inside_longer_word(prefix):
    """True when the newest token is a word piece glued onto a letter before it,
    as "in" in "surviv|in", so it is not the preposition."""
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or token[:1].isspace() or not token[:1].isalpha():
        return False
    return prefix.token_strings[-2][-1:].isalpha()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    base = PREPOSITIONS.get(word, 0.0)
    if base == 0.0 or _inside_longer_word(prefix):
        return None, 0.0
    value = base
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc:
        before = _word(prefix.token_strings[-2])
        if before in USAGE:
            value += USAGE_BOOST
        elif before in SEARCH_OR_PLACE:
            value -= SEARCH_PENALTY
        elif before.endswith("ed") and len(before) > 3:
            value -= PARTICIPLE_PENALTY
    return None, float(value)

programs.luna:
"""Approximate a rare lexical cue for English relations such as 'in' and 'for'.
The component is usually quiet, but often adds a positive signal on these words.
"""

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if word == "in":
        return None, 0.32 if raw == "IN" else 1.05
    if word == "for":
        return None, 0.95
    if word == "when":
        return None, 0.65
    if word == "في":
        return None, 0.22
    return None, 0.0

"""Estimate a few strong relation-word responses in this mostly quiet component.

Its largest negative responses cluster on Chinese words for having, belonging,
being located, and meeting a condition.  Source, inclusion, and role words are
similar cues.  Most other Han characters get only a small shared offset;
unrelated tokens get zero.
"""

import unicodedata

READS = ()

PRESENCE = {
    "有", "存在", "具有", "拥有", "享有", "含有", "包含", "具备",
}
LOCATION = {
    "位于", "位於", "处于", "處於", "坐在", "站在", "躺在",
    "停留在", "出现在", "落在", "放在", "居", "进入", "走进",
}
RELATION = {
    "属", "屬", "属于", "於", "于", "来自", "來自", "源自",
    "来源于", "來源於", "涉及", "涉及到", "归咎于", "有利于",
    "有助于", "依赖", "依靠", "取决于", "超过", "接近", "适合",
    "关于", "由于", "列入", "列为", "从事", "离不开", "像是",
}
CONDITION = {"符合", "不符合", "不适合", "满足"}
LINK_WORDS = {"以", "为", "到", "是", "作为", "成为"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in LOCATION:
        value = -1.7
    elif word in CONDITION:
        value = -1.8
    elif word in PRESENCE:
        value = -0.8
    elif word in RELATION:
        value = -0.9
    elif word in LINK_WORDS:
        value = {
            "以": -0.7, "为": -0.5, "到": -0.3, "是": -0.3,
            "作为": -0.4, "成为": -0.4,
        }[word]
    elif word.lower() in {"belong", "belongs", "belonged", "belonging"}:
        value = -1.0
    elif any("CJK" in unicodedata.name(char, "") for char in word):
        value = -0.02
    else:
        value = 0.0
    return None, float(value)

"""Give selected, familiar prefix-like token spellings small negative scores."""

READS = ()

STRONG_PREFIXES = {"non", "anti", "pre", "multi"}
OTHER_PREFIXES = {
    "inter", "post", "mid", "meta", "pseudo", "poly", "socio",
    "tele", "micro", "sub", "co", "pro", "intra", "psycho",
    "seud", "soci",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    spelling = raw.strip().lstrip("-_").casefold()
    if spelling in STRONG_PREFIXES:
        return None, -1.5
    if spelling in OTHER_PREFIXES:
        return None, -0.65
    return None, 0.0

programs.sol:
"""A lexical needle/pointing detector, not a general metal detector.

Needles (especially 针/針) give the largest positive response. Pointers,
targeting/addressing, needlework, small metal tools, and pointed shapes
have weaker responses.
The previous token helps distinguish addressing a problem from an IP/email
address, join inflectional suffixes, and recognize split Chinese characters.
Everything else is zero; contextual and unrelated lexical variation is omitted.
"""

READS = ()

ADDRESS = {'address', 'addresses', 'addressed', 'addressing'}
TARGET = {'targeted', 'targeting', 'tailored', 'tackle', 'workaround'}
POINT = {'pointed', 'pointing', 'pinpoint'}
TOOLS = {'hammer', 'hammered', 'knife', 'knives', 'dagger'}
NEEDLEWORK = {'stitch', 'stitches', 'stitching', 'crochet'}
SMALL_TOOLS = {'pin', 'nail', 'hook'}
ADDRESS_LABELS = {'ip', 'mac', 'email', 'e-mail', 'memory', 'contract'}


def lexical_value(s):
    word = s.strip().lstrip('._-').lower()
    if word in {'needle', 'needles'}:
        if not s[:1].isspace():
            return 1.3
        return 2.65 if s.strip().istitle() else 2.25
    if word in {'pointer', 'pointers'}:
        return 1.22 if word == 'pointer' else 0.95
    if word == 'acupuncture':
        return 1.05
    if word in ADDRESS:
        return 0.61 if word.endswith(('ed', 'ing')) else 0.46
    if word in TARGET:
        return 0.66 if word in {'targeted', 'tailored'} else 0.48
    if word in POINT:
        return 0.75 if word == 'pinpoint' else 0.40
    for words, value in ((TOOLS, 0.55), (NEEDLEWORK, 0.45),
                         (SMALL_TOOLS, 0.25)):
        if word in words:
            return value
    if word in {'spoon', 'poon'}:
        return 0.69
    if word in {'drill', 'drilled', 'drilling'}:
        return 0.85 if word == 'drill' else 0.6
    if word in {'chain', 'chains', 'clock', 'clocks', 'triangle',
                'triangles', 'diagonal', 'necklace', 'bracelet'}:
        return 0.35
    if word in {'coin', 'coins'}:
        return 0.2

    if s in {'针', '針'}:
        return 4.6 if s == '针' else 4.1
    if s in {'针对', '針對'}:
        return 3.55 if s == '针对' else 2.6
    if '针对性' in s or '針對性' in s:
        return 2.05
    if '针' in s or '針' in s:
        return 1.0
    if s == '钥匙':
        return 1.55
    if s in '钟鐘鍾锺' and len(s) == 1:
        return 1.5
    if s == '刺':
        return 1.2
    if s in {'钻', '鑽'}:
        return 1.0
    if s in '链鏈鍊匙' and len(s) == 1:
        return 0.75
    if s in '钱錢锁鎖钉釘刀珠' and len(s) == 1:
        return 0.58
    if s in '镜鏡钩鈎锤錘指' and len(s) == 1:
        return 0.35
    return 0.0


# These IDs name UTF-8 fragments, rather than arbitrary vocabulary entries.
# E9 92 contains 针/钉; E9 8D and E9 95 contain metal-radical characters.
METAL_LEAD = {165, 18137}  # E9, or space + E9
METAL_SECOND = {235: 1.47, 240: 4.4, 243: 1.35}  # 8D, 92, 95
TRADITIONAL_METAL_PREFIX = 101838  # E9 8D


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_id = ('', -1)
    if carry is not None and carry[0] == doc:
        previous, previous_id = carry[1:]
    s = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if token_id == TRADITIONAL_METAL_PREFIX:
        value = 1.47
    elif previous_id in METAL_LEAD and token_id in METAL_SECOND:
        value = METAL_SECOND[token_id]
    else:
        split = '\ufffd' in s
        if split:
            s = prefix.text_prefixes[-1][-1:] if previous_id != -1 else ''
        if s in {'ed', 'ing', 's'}:
            value = lexical_value(previous + s)
        elif s == '对' and previous == '针':
            value = 1.35
        else:
            value = lexical_value(s)
            if split and s == '针':
                value = 6.35
            if s.strip().lower() in {'address', 'addresses'}:
                before = previous.strip().lower()
                if before in ADDRESS_LABELS:
                    value = 0.13 if before in {'email', 'e-mail'} else 0.23
                elif before == 'to':
                    value = 0.66
    return (doc, s, token_id), float(value)

"""Respond to an opening parenthesis fused with an identifier in one token.

Single-letter identifiers give a smaller response than longer names. Common
self-references, boolean literals and function-expression keywords are weaker
than ordinary names. Underscore-led identifiers also have a lower response.
A bare opening parenthesis gets a small response; other tokens get zero.
No earlier context is used.
"""

READS = ()
SELF_REFERENCES = {"self", "this"}
BOOLEAN_LITERALS = {"true", "false"}
FUNCTION_EXPRESSIONS = {"function", "lambda"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = 0.0
    if token == "(":
        value = 0.10
    elif token.startswith("(") and token[1:].isidentifier():
        name = token[1:]
        if name in SELF_REFERENCES:
            value = 1.62
        elif name in BOOLEAN_LITERALS:
            value = 1.52
        elif name in FUNCTION_EXPRESSIONS:
            value = 1.40
        elif name.startswith("_"):
            value = 1.25
        elif len(name) == 1:
            value = 1.51
        else:
            value = 2.06 + 0.06 * min(len(name), 10)
    return None, float(value)
